import subprocess,os,shutil,json
def gen(name, files, cfg=None, extra=[]):
    base=f"/tmp/exp/fm_{name}"; shutil.rmtree(base,ignore_errors=True); os.makedirs(base+"/in")
    for k,v in files.items():
        p=os.path.join(base+"/in",k); os.makedirs(os.path.dirname(p),exist_ok=True); open(p,"w").write(v)
    if cfg: open(base+"/in/marmite.yaml","w").write(cfg)
    r=subprocess.run(["./executable",base+"/in",base+"/out"]+extra,capture_output=True,text=True)
    print(name, r.returncode, r.stderr[:800])
    if os.path.exists(base+"/out"): print(sorted([f for f in os.listdir(base+"/out") if f!='static']))
    if os.path.exists(base+"/out/marmite.json"):
        j=json.load(open(base+"/out/marmite.json")); print("posts",j["posts"],"pages",j["pages"])
    if os.path.exists(base+"/out/urls.json"): print(open(base+"/out/urls.json").read())
    print()
    return base

