import subprocess,os,shutil,re
def gen(name,files,cfg=None,extra=[]):
    base=f"/tmp/exp/np_{name}"; shutil.rmtree(base,ignore_errors=True); os.makedirs(base+"/in")
    for k,v in files.items(): open(base+"/in/"+k,"w").write(v)
    if cfg: open(base+"/in/marmite.yaml","w").write(cfg)
    r=subprocess.run(["./executable",base+"/in",base+"/out"]+extra,capture_output=True,text=True)
    print(name,r.returncode,r.stderr[:500])
    if os.path.exists(base+"/out"):
        for f in sorted(os.listdir(base+"/out")):
            if f.endswith(".html") and f[0].islower():
                t=open(base+"/out/"+f).read()
                nav=re.findall(r'<a href="[^"]*">([^<]*(?:←|→)[^<]*|[^<]+(?:←|→))</a>',t)
                rel=re.search(r'Related .*?content(.*?)</article>',t,re.S)
                back=re.search(r'Back-links(.*?)</article>',t,re.S)
                print(f, nav, "back:",re.findall(r'>([^<]+)</a>',back.group(1)) if back else None, "related:",re.findall(r'>([^<]+)</a>',rel.group(1)) if rel else None)
    print()
