    def parse_block(min_indent):
        node_line=peek()
        if node_line is None: return None
        indent, content, lno, raw = node_line
        if indent < min_indent:
            return None
        # list?
        if content=='-' or content.startswith('- '):
            return parse_list(indent)
        # mapping? key: ...
        # A key line: find colon not in quotes/flow followed by space or EOL
        if _find_yaml_key_colon(content) is not None:
            return parse_map(indent)
        # scalar (possibly multiline plain? take this line only)
        pos[0]+=1
        return _parse_yaml_scalar(content, lno)
