            if in_s:
                if ch=="'": in_s=False
            elif in_d:
                if ch=='"': in_d=False
            else:
                if ch=="'": in_s=True
                elif ch=='"': in_d=True
                elif ch in '[{': depth+=1
                elif ch in ']}': depth-=1
                elif ch==':' and depth==0:
                    if i==len(s)-1 or s[i+1] in ' \t':
                        return i
        return None
