            if colon is None:
                raise YamlError("did not find expected key", line=lno, column=ind+1, context="while parsing a block mapping")
            key_src=content[:colon].strip()
            if key_src=='':
                raise YamlError("did not find expected key", line=lno, column=ind+1, context="while parsing a block mapping")
