                if ch=="'": in_s=False
            elif in_d:
                if ch=='"': in_d=False
            else:
                if ch=="'": in_s=True
                elif ch=='"': in_d=True
                elif ch in '[{': bal+=1
                elif ch in ']}': bal-=1
