def yaml_scalar(v):
    if v is None: return "null"
    if v is True: return "true"
    if v is False: return "false"
    if isinstance(v, int): return str(v)
    if isinstance(v, float):
        if v==int(v): return str(v) if '.' in str(v) else str(v)
        return repr(v)
    s=str(v)
    if s=='':
        return "''"
    # serde_yaml quoting heuristics approx
    needs=False
    if s != s.strip(): needs=True
    if any(c in s for c in ['\n','\r','\t']): needs=True
    if ': ' in s or s.endswith(':'): needs=True
    if s[0] in '!&*?|>%@`#,[]{}:\'"' or s[0]=='-' and (len(s)==1 or s[1]==' '): needs=True
    if s.lower() in ('true','false','null','~','yes','no','on','off'): needs=True
    if re.fullmatch(r'-?[0-9][0-9_]*(\.[0-9]*)?', s): needs=True
    if ' #' in s: needs=True
    if needs:
        if '\n' in s:
            return json.dumps(s)
        return "'" + s.replace("'","''") + "'"
    return s

def dump_yaml(data, indent=0):
    lines=[]
    prefix='  '*indent
    if isinstance(data, dict):
        if not data:
            return "{}\n"
        for k,v in data.items():
            ks=yaml_scalar(str(k)) if not isinstance(k,str) or _yaml_key_needs_quote(str(k)) else str(k)
            if isinstance(v, dict):
                if not v:
                    lines.append(f"{prefix}{ks}: {{}}")
                else:
                    lines.append(f"{prefix}{ks}:")
                    lines.append(dump_yaml(v, indent+1).rstrip('\n'))
            elif isinstance(v, list):
                if not v:
                    lines.append(f"{prefix}{ks}: []")
                else:
                    lines.append(f"{prefix}{ks}:")
                    lines.append(dump_yaml(v, indent).rstrip('\n'))  # serde_yaml list items at same indent as key for nested? handled below
            else:
                lines.append(f"{prefix}{ks}: {yaml_scalar(v)}")
        return "\n".join(lines)+"\n"
    elif isinstance(data, list):
        if not data: return "[]\n"
        for item in data:
            if isinstance(item, dict):
                if not item:
                    lines.append(f"{prefix}- {{}}")
                else:
                    sub=dump_yaml(item, indent+1).rstrip('\n').split('\n')
                    # first line gets - 
                    first=sub[0]
                    lines.append(f"{prefix}- {first.strip()}")
                    for s in sub[1:]:
                        lines.append(s)
            elif isinstance(item, list):
                if not item:
                    lines.append(f"{prefix}- []")
                else:
                    sub=dump_yaml(item, indent+1).rstrip('\n').split('\n')
                    first=sub[0]
                    # sub lines start with indent+1 prefix and '-'
                    lines.append(f"{prefix}- {first.strip()}")
                    for s in sub[1:]:
                        lines.append(s)
            else:
                lines.append(f"{prefix}- {yaml_scalar(item)}")
        return "\n".join(lines)+"\n"
    else:
        return yaml_scalar(data)+"\n"

def _yaml_key_needs_quote(s):
    return s=='' or ': ' in s or s.strip()!=s

def dump_config_yaml(cfg):
    # Config serialization matches serde_yaml output for the Config struct order.
    # Use generic dump but list indentation for menu needs special handling to match reference:
    # menu:
    # - - Tags
    #   - tags.html
    # Our dump_yaml produces that pattern when list items are lists (check).
    return dump_yaml(cfg)

