def _jsonable(v):
    if isinstance(v, datetime):
        return v.strftime("%Y-%m-%dT%H:%M:%S")
    if isinstance(v, dict):
        return {str(k):_jsonable(val) for k,val in v.items()}
    if isinstance(v,(list,tuple)):
        return [_jsonable(x) for x in v]
    return v

