            fm=re.match(r'^[ ]{0,3}(```+|~~~+)[ \t]*([^\s`~]*)[^\n]*$', line)
            if fm:
                marker=fm.group(1); char=marker[0]; count=len(marker); lang=fm.group(2) or ''
                code_lines=[]; i+=1
                while i < n:
                    if re.match(r'^[ ]{0,3}'+re.escape(char)+r'{'+str(count)+r',}[ \t]*$', lines[i]):
                        i+=1; break
                    code_lines.append(lines[i]); i+=1
                code='\n'.join(code_lines)
                if code_lines: code+='\n'
                cls=f' class="language-{html_escape_attr(lang)}"' if lang else ''
                html_parts.append(f"<pre><code{cls}>{html_escape_attr(code)}</code></pre>\n")
                continue
            # HTML block / comment
            if self._is_html_block_start(line):
                block=[]
                # script/pre/style/textarea until closing tag? Simplify: until blank line, or if starts with comment until -->
                if line.lstrip().startswith('<!--'):
                    while i < n:
                        block.append(lines[i]); i+=1
                        if '-->' in block[-1]: break
                    html_parts.append('\n'.join(block)+'\n')
                    continue
                while i < n and lines[i].strip()!='':
                    block.append(lines[i]); i+=1
                html_parts.append('\n'.join(block)+'\n')
                continue
            # ATX heading
            hm=re.match(r'^[ ]{0,3}(#{1,6})(?:[ \t]+(.*?))?[ \t]*$', line)
            if hm and (hm.group(2) is not None or True):
                # Require space after hashes if there is content glued? comrak requires space; our regex handles "#foo" as hashes with no group2? Actually #foo won't match because after # need space or EOL via optional group with space; test: pattern would match # only and foo left unmatched -> but second part [ \t]*$ prevents? "#foo" substring: #{1,6} matches #, optional group empty, [ \t]*$ fails on foo, backtrack fail. Good.
                level=len(hm.group(1)); content=(hm.group(2) or '').strip()
                content=re.sub(r'[ \t]+#+[ \t]*$', '', content)
                html_parts.append(self._render_heading(level, content))
                i+=1; continue
            # thematic break (but setext handled in paragraph collection; --- after blank is hr)
            if re.match(r'^[ ]{0,3}(?:(?:-[ \t]*){3,}|(?:\*[ \t]*){3,}|(?:_[ \t]*){3,})$', line):
                html_parts.append('<hr />\n'); i+=1; continue
            # blockquote
            if re.match(r'^[ ]{0,3}>', line):
                qlines=[]; 
                while i < n:
                    if re.match(r'^[ ]{0,3}>', lines[i]):
                        q=re.sub(r'^[ ]{0,3}>[ \t]?', '', lines[i]); qlines.append(q); i+=1
                    elif lines[i].strip()!='' and qlines and qlines[-1].strip()!='':
                        # lazy continuation only if current q content is paragraph-ish (approx: always)
                        qlines.append(lines[i]); i+=1
                    else:
                        break
                html_parts.append(self._render_blockquote(qlines)); continue
            # list
            if self._list_item_match(line) is not None:
                lst_html, i = self._render_list(lines, i, self._indent_of(line))
                html_parts.append(lst_html); continue
            # table detection: current line contains | and next line delimiter
            if '|' in line and i+1 < n and self._is_table_delim(lines[i+1]):
                thtml, i = self._render_table(lines, i); html_parts.append(thtml); continue
            # description list: term line followed by : definition
            if i+1 < n and re.match(r'^[ ]{0,3}:[ \t]+', lines[i+1] or ''):
                dhtml, i=self._render_desc_list(lines,i); html_parts.append(dhtml); continue
            # indented code
            if line.startswith('    ') or line.startswith('\t'):
                code_lines=[]
                while i < n and (lines[i].startswith('    ') or lines[i].startswith('\t') or lines[i].strip()==''):
                    if lines[i].strip()=='':
                        # include blank if followed by indented
                        j=i+1
                        while j < n and lines[j].strip()=='':
                            j+=1
                        if j < n and (lines[j].startswith('    ') or lines[j].startswith('\t')):
                            code_lines.append(''); i+=1; continue
                        break
                    code_lines.append(lines[i][4:] if lines[i].startswith('    ') else lines[i][1:]); i+=1
                code='\n'.join(code_lines)+'\n' if code_lines else ''
                html_parts.append(f"<pre><code>{html_escape_attr(code)}</code></pre>\n"); continue
            # paragraph (collect until blank or block start), check setext heading on second line
            para_lines=[line.strip()]; i+=1; is_setext=None
            while i < n:
                nl=lines[i]
                if nl.strip()=='':
                    break
                if len(para_lines)==1 and re.match(r'^[ ]{0,3}=+[ \t]*$', nl):
                    is_setext=1; i+=1; break
                if len(para_lines)==1 and re.match(r'^[ ]{0,3}-+[ \t]*$', nl):
                    is_setext=2; i+=1; break
                if self._starts_block(nl, lines, i):
                    break
                para_lines.append(nl.strip()); i+=1
            para_text='\n'.join(para_lines)
            if is_setext:
                html_parts.append(self._render_heading(is_setext, para_text))
            else:
                html_parts.append(f"<p>{self.render_inline(para_text)}</p>\n")
        return ''.join(html_parts)

    def _is_html_block_start(self, line):
        s=line.lstrip()
        if s.startswith('<!--') or s.startswith('<?') or s.startswith('<!'):
            # <! could be doctype/cdata - only if letter or [
            if s.startswith('<!') and not (s.startswith('<!--') or re.match(r'<!\[CDATA\[',s) or re.match(r'<![A-Za-z]',s)):
                return False
            return True
        m=re.match(r'^</?([A-Za-z][A-Za-z0-9-]*)(?:[ \t/>]|$)', s)
        if not m: return False
        # html block tags list for type 6, plus any tag as type7 if complete tag on line alone-ish
        block_tags={"address","article","aside","base","basefont","blockquote","body","caption","center","col","colgroup","dd","details","dialog","dir","div","dl","dt","fieldset","figcaption","figure","footer","form","frame","frameset","h1","h2","h3","h4","h5","h6","head","header","hr","html","iframe","legend","li","link","main","menu","menuitem","nav","noframes","ol","optgroup","option","p","param","section","source","summary","table","tbody","td","tfoot","th","thead","title","tr","track","ul","script","pre","style","textarea"}
        if m.group(1).lower() in block_tags:
            return True
        # type7: a complete open/closing tag followed by whitespace/EOL and line is not paragraph continuation (we are at block start)
        if re.match(r'^</?[A-Za-z][^>]*>[ \t]*$', s) or re.match(r'^</?[A-Za-z][^>]*>[ \t]', s):
            # In observed simple case <div>raw</div> works. But a line starting <b>inline</b> text would be paragraph in commonmark type7 cannot interrupt paragraph, but at block start it can be html block? comrak treats as html block if tag alone? Keep paragraph for inline tags with other text.
            # if line contains closing corresponding and more text, still raw in paragraph? Earlier raw html test was just <div>...
            return bool(re.match(r'^</?[A-Za-z][^>]*>[ \t]*$', s))
        return False

    def _starts_block(self, line, lines, idx):
        if re.match(r'^[ ]{0,3}(```+|~~~+)', line): return True
        if re.match(r'^[ ]{0,3}#{1,6}(?:[ \t]+|$)', line): return True
        if re.match(r'^[ ]{0,3}>', line): return True
        if self._list_item_match(line) is not None:
            # lists can interrupt paragraph only if not empty and ordered starts 1 (approx allow)
            return True
        if re.match(r'^[ ]{0,3}(?:(?:-[ \t]*){3,}|(?:\*[ \t]*){3,}|(?:_[ \t]*){3,})$', line): return True
        if self._is_html_block_start(line): return True
        if '|' in line and idx+1 < len(lines) and self._is_table_delim(lines[idx+1]): return True
        return False

    def _render_heading(self, level, content):
        plain=self._inline_plain_text(content)
        anchor=anchor_slug(plain, self.used_anchors)
        self.headings.append((level, plain, anchor))
        inline=self.render_inline(content)
        return f'<h{level}><a href="#{anchor}" aria-hidden="true" class="anchor" id="{anchor}"></a>{inline}</h{level}>\n'

    def _render_blockquote(self, qlines):
        # alert check first non-empty line
        idx=0
        while idx < len(qlines) and qlines[idx].strip()=='':
            idx+=1
        if idx < len(qlines):
            m=re.match(r'^\[!(NOTE|TIP|IMPORTANT|WARNING|CAUTION)\][ \t]*$', qlines[idx].strip(), re.I)
            if m:
                kind=m.group(1).lower()
                title=kind.capitalize()
                rest=qlines[idx+1:]
                inner=self._render_blocks(rest)
                return f'<div class="markdown-alert markdown-alert-{kind}">\n<p class="markdown-alert-title">{title}</p>\n{inner}</div>\n'
        inner=self._render_blocks(qlines)
        return f'<blockquote>\n{inner}</blockquote>\n'

    def _indent_of(self, line):
        # count spaces, tab as 4
        c=0
        for ch in line:
            if ch==' ': c+=1
            elif ch=='\t': c+=4
            else: break
        return c

    def _list_item_match(self, line):
        # returns dict or None
        m=re.match(r'^([ ]{0,3})([-+*])[ \t]+(.*)$', line)
        if m:
            return {"indent":len(m.group(1)), "ordered":False, "marker":m.group(2), "content":m.group(3), "number":None, "marker_width":len(m.group(1))+2}
        m=re.match(r'^([ ]{0,3})(\d{1,9})([.)])[ \t]+(.*)$', line)
        if m:
            return {"indent":len(m.group(1)), "ordered":True, "marker":m.group(3), "content":m.group(4), "number":int(m.group(2)), "marker_width":len(m.group(1))+len(m.group(2))+2}
        return None

    def _render_list(self, lines, start_i, base_indent):
        i=start_i
        first=self._list_item_match(lines[i])
        ordered=first["ordered"]; start_num=first.get("number")
        items=[]  # list of list-of-lines (content)
        loose=False
        while i < len(lines):
            line=lines[i]
            m=self._list_item_match(line)
            if m is None or m["indent"] < base_indent or m["indent"] > base_indent+3:
                break
            if m["ordered"] != ordered:
                # changing ordered delimiter? if same level but diff type stops
                if items: break
            # content indent: marker width (approx position of content)
            # compute content column: indent + marker length + spaces
            content_col = self._content_column(line, m)
            item_lines=[m["content"]]
            i+=1
            # collect continuation
            while i < len(lines):
                nl=lines[i]
                if nl.strip()=='':
                    # lookahead: if next is item at base or indented content, include blank => loose
                    j=i+1
                    while j < len(lines) and lines[j].strip()=='':
                        j+=1
                    if j>=len(lines):
                        i=j; break
                    nm=self._list_item_match(lines[j])
                    if nm is not None and nm["indent"]>=base_indent and nm["indent"]<=base_indent+3 and nm["ordered"]==ordered:
                        # blank between items makes loose if more than? Commonmark blank between items -> loose
                        loose=True
                        i+=1; break
                    if self._indent_of(lines[j]) >= content_col:
                        loose=True
                        item_lines.append('')
                        i+=1; continue
                    # blank ends list
                    i+=1; break
                nm=self._list_item_match(nl)
                if nm is not None and nm["indent"]>=base_indent and nm["indent"]<=base_indent+3:
                    # could be nested list if indent >= content_col
                    if self._indent_of(nl) >= content_col:
                        # nested list will be handled when rendering item blocks if we keep indentation relative
                        item_lines.append(nl[content_col:] if len(nl)>=content_col else nl.lstrip())
                        i+=1; continue
                    break
                if self._indent_of(nl) >= content_col:
                    item_lines.append(nl[content_col:])
                    i+=1; continue
                # lazy continuation line for paragraph
                # if it doesn't start a new block at base level, treat as continuation
                if not self._starts_block(nl, lines, i):
                    item_lines.append(nl.strip())
                    i+=1; continue
                break
            items.append(item_lines)
            # continue loop; if next line is blank handled
            # peek if blank lines then next item was handled? above breaks handling.
        # Determine loose: if any item contains blank line separating blocks (excluding trailing)
        for it in items:
            # strip trailing blanks
            while it and it[-1].strip()=='':
                it.pop()
            if '' in it:
                loose=True
        tag='ol' if ordered else 'ul'
        attrs=''
        if ordered and start_num not in (None,1):
            attrs=f' start="{start_num}"'
        out=[f'<{tag}{attrs}>']
        for it in items:
            # task list check on first line
            task=None
            if it:
                tm=re.match(r'^\[([ xX])\][ \t]+(.*)$', it[0])
                if tm:
                    task=(tm.group(1).lower()=='x')
                    it[0]=tm.group(2)
            inner=self._render_blocks(it)
            if not loose:
                # Tight: unwrap <p>...</p> for paragraph blocks but keep other blocks.
                # Replace <p>X</p> at top-level with X (simple regex for paragraphs that are whole chunks)
                inner=re.sub(r'<p>(.*?)</p>\n', lambda mm: mm.group(1)+'\n', inner, flags=re.S)
                inner=inner.rstrip('\n')
                if task is not None:
                    checkbox='<input type="checkbox" checked="" disabled="" /> ' if task else '<input type="checkbox" disabled="" /> '
                    inner=checkbox+inner
                if '\n' in inner:
                    out.append(f'<li>{inner}\n</li>')
                else:
                    out.append(f'<li>{inner}</li>')
            else:
                inner=inner.rstrip('\n')
                if task is not None:
                    checkbox='<input type="checkbox" checked="" disabled="" /> ' if task else '<input type="checkbox" disabled="" /> '
                    # task in loose: checkbox inside first <p> if present
                    if inner.startswith('<p>'):
                        inner='<p>'+checkbox+inner[3:]
                    else:
                        inner=checkbox+inner
                out.append('<li>')
                out.append(inner)
                out.append('</li>')
        out.append(f'</{tag}>')
        return '\n'.join(out)+'\n', i

    def _content_column(self, line, m):
        # Index where content starts in raw line (spaces count)
        # find marker then spaces
        if m["ordered"]:
            pattern=r'^[ ]*\d+[.)][ \t]+'
        else:
            pattern=r'^[ ]*[-+*][ \t]+'
        mm=re.match(pattern, line)
        return mm.end() if mm else m["indent"]+2

    def _is_table_delim(self, line):
        s=line.strip()
        if '|' not in s and '-' not in s: return False
        cells=self._split_table_row(s)
        if not cells: return False
        for c in cells:
            if not re.fullmatch(r':?-{3,}:?|:?-+:?', c.strip()):
                return False
            if '-' not in c: return False
        return True

    def _split_table_row(self, line):
        s=line.strip()
        if s.startswith('|'): s=s[1:]
        if s.endswith('|') and not s.endswith('\\|'): s=s[:-1]
        cells=[]; cur=''; in_code=False; esc=False
        for ch in s:
            if esc:
                cur+=ch; esc=False; continue
            if ch=='\\':
                cur+=ch; esc=True; continue
            if ch=='`': in_code=not in_code; cur+=ch; continue
            if ch=='|' and not in_code:
                cells.append(cur); cur=''; continue
            cur+=ch
        cells.append(cur)
        return [c.strip() for c in cells]

    def _render_table(self, lines, i):
        header=self._split_table_row(lines[i])
        delim=self._split_table_row(lines[i+1])
        aligns=[]
        for c in delim:
            c=c.strip()
            if c.startswith(':') and c.endswith(':'): aligns.append('center')
            elif c.endswith(':'): aligns.append('right')
            elif c.startswith(':'): aligns.append('left')
            else: aligns.append(None)
        i+=2
        rows=[]
        while i < len(lines) and lines[i].strip()!='' and '|' in lines[i]:
            rows.append(self._split_table_row(lines[i])); i+=1
        out=['<table>','<thead>','<tr>']
        for idx,h in enumerate(header):
            align=aligns[idx] if idx < len(aligns) else None
            attr=f' align="{align}"' if align else ''
            out.append(f'<th{attr}>{self.render_inline(h)}</th>')
        out.append('</tr>'); out.append('</thead>')
        if rows:
            out.append('<tbody>')
            for r in rows:
                out.append('<tr>')
                for idx in range(len(header)):
                    cell=r[idx] if idx < len(r) else ''
                    align=aligns[idx] if idx < len(aligns) else None
                    attr=f' align="{align}"' if align else ''
                    out.append(f'<td{attr}>{self.render_inline(cell)}</td>')
                out.append('</tr>')
            out.append('</tbody>')
        out.append('</table>')
        return '\n'.join(out)+'\n', i

    def _render_desc_list(self, lines, i):
        out=['<dl>']
        while i < len(lines) and lines[i].strip()!='':
            # term lines until :
            terms=[]
            while i < len(lines) and not re.match(r'^[ ]{0,3}:[ \t]+', lines[i]) and lines[i].strip()!='':
                terms.append(lines[i].strip()); i+=1
            for t in terms:
                out.append(f'<dt>{self.render_inline(t)}</dt>')
            while i < len(lines) and re.match(r'^[ ]{0,3}:[ \t]+', lines[i]):
                dd=re.sub(r'^[ ]{0,3}:[ \t]+','',lines[i]).strip(); i+=1
                # continuation indented? ignore simple
                out.append(f'<dd>{self.render_inline(dd)}</dd>')
            if i < len(lines) and lines[i].strip()=='':
                # peek if next is term+dd
                j=i
                while j < len(lines) and lines[j].strip()=='':
                    j+=1
                if j+1 < len(lines) and re.match(r'^[ ]{0,3}:[ \t]+', lines[j+1]):
                    i=j; continue
                i=j; break
        out.append('</dl>')
        return '\n'.join(out)+'\n', i

    # ---- inline ----
    def _inline_plain_text(self, s):
        # render inline then strip tags and unescape
        h=self.render_inline(s)
        return html.unescape(strip_tags(h))

    def render_inline(self, s):
        return self._parse_inline(s, 0, len(s))

    def _parse_inline(self, s, start, end):
        out=[]
        i=start
        while i < end:
            c=s[i]
            # hard break: backslash before newline or two spaces before newline handled as char sequence
            if c=='\\' and i+1<end:
                nxt=s[i+1]
                if nxt=='\n':
                    out.append('<br />\n'); i+=2; continue
                if nxt in '\\`*_{}[]()#+-.!>|~':
                    out.append(html_escape_attr(nxt)); i+=2; continue
                out.append('\\'); i+=1; continue
            # newline / hard break from trailing spaces
            if c=='\n':
                # check preceding text in out for two spaces? Our source: look back in s
                if i>=2 and s[i-2:i]=='  ':
                    # remove trailing two spaces from out text if present
                    # out last may include spaces; strip them
                    # Simplification: trim trailing spaces in joined (rebuild)
                    joined=''.join(out)
                    joined=joined.rstrip(' ')
                    out=[joined, '<br />\n']
                else:
                    out.append('\n')
                i+=1; continue
            # code span
            if c=='`':
                j=i
                while j<end and s[j]=='`': j+=1
                ticks=j-i
                # find closing same number
                close=self._find_code_close(s,j,end,ticks)
                if close!=-1:
                    code=s[j:close].replace('\n',' ')
                    if len(code)>2 and code[0]==' ' and code[-1]==' ' and code.strip()!='':
                        code=code[1:-1]
                    out.append(f'<code>{html_escape_attr(code)}</code>')
                    i=close+ticks; continue
                out.append('`'*ticks); i=j; continue
            # footnote ref, image/link, wikilink
            if c=='!' and i+1<end and s[i+1]=='[':
                parsed=self._try_parse_link(s,i,end,is_image=True)
                if parsed:
                    html_out, ni=parsed; out.append(html_out); i=ni; continue
                out.append('!'); i+=1; continue
            if c=='[':
                # wikilink [[...]]
                if i+1<end and s[i+1]=='[':
                    close=s.find(']]', i+2, end)
                    if close!=-1:
                        inner=s[i+2:close]
                        out.append(self._render_wikilink(inner)); i=close+2; continue
                # footnote ref
                fnm=re.match(r'\[\^([^\]\s]+)\]', s[i:end])
                if fnm:
                    label=fnm.group(1)
                    key=_norm_ref_label(label)
                    if key in self.footnotes:
                        if key not in [ _norm_ref_label(x) for x in self.footnote_order]:
                            self.footnote_order.append(label)
                        idx=[_norm_ref_label(x) for x in self.footnote_order].index(key)+1
                        # data-footnote-ref idx handling for repeat refs: comrak uses fnref-idx with suffix; simple first only
                        count=self.footnote_ref_counts.get(key,0)+1; self.footnote_ref_counts[key]=count
                        ref_id=f'fnref-{idx}' if count==1 else f'fnref-{idx}-{count-1}'
                        out.append(f'<sup class="footnote-ref"><a href="#fn-{idx}" id="{ref_id}" data-footnote-ref>{idx}</a></sup>')
                        i+=len(fnm.group(0)); continue
                parsed=self._try_parse_link(s,i,end,is_image=False)
                if parsed:
                    html_out, ni=parsed; out.append(html_out); i=ni; continue
                out.append('['); i+=1; continue
            # autolink <...> or raw html
            if c=='<':
                # comment
                if s.startswith('<!--', i):
                    close=s.find('-->', i+4, end)
                    if close!=-1:
                        out.append(s[i:close+3]); i=close+3; continue
                # autolink uri/email
                close=s.find('>', i+1, end)
                if close!=-1:
                    inside=s[i+1:close]
                    if re.fullmatch(r'[A-Za-z][A-Za-z0-9+.-]{1,31}:[^\s<>]*', inside):
                        out.append(f'<a href="{html_escape_attr(inside)}">{html_escape_attr(inside)}</a>'); i=close+1; continue
                    if re.fullmatch(r'[^@\s<>]+@[^@\s<>]+\.[^@\s<>]+', inside):
                        out.append(f'<a href="mailto:{html_escape_attr(inside)}">{html_escape_attr(inside)}</a>'); i=close+1; continue
                    # raw tag
                    if re.match(r'^/?[A-Za-z][^>]*$', inside) or inside.startswith('!') or inside.startswith('?'):
                        out.append(s[i:close+1]); i=close+1; continue
                out.append('&lt;'); i+=1; continue
            # spouse spoiler ||
            if c=='|' and s.startswith('||', i):
                close=s.find('||', i+2, end)
                if close!=-1 and close>i+2:
                    inner=self._parse_inline(s,i+2,close)
                    out.append(f'<span class="spoiler">{inner}</span>'); i=close+2; continue
            # emphasis / strong / underline / strike
            if c in '*_~':
                parsed=self._try_parse_emphasis(s,i,end)
                if parsed:
                    html_out, ni=parsed; out.append(html_out); i=ni; continue
                out.append(html_escape_attr(c)); i+=1; continue
            # bare autolinks / emails (extension)
            if c.isalnum() and (i==start or s[i-1] in ' \t\n([{"\''):
                m=re.match(r'(https?://|ftp://|www\.)[^\s<>]+', s[i:end])
                if m:
                    raw=m.group(0)
                    raw=self._trim_autolink(raw)
                    href=raw
                    if raw.startswith('www.'): href='http://'+raw
                    out.append(f'<a href="{html_escape_attr(href)}">{html_escape_attr(raw)}</a>')
                    i+=len(raw); continue
                m=re.match(r'[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}', s[i:end])
                if m:
                    raw=m.group(0)
                    out.append(f'<a href="mailto:{html_escape_attr(raw)}">{html_escape_attr(raw)}</a>')
                    i+=len(raw); continue
            # entity
            if c=='&':
                m=re.match(r'&(#x[0-9A-Fa-f]+|#[0-9]+|[A-Za-z][A-Za-z0-9]+);', s[i:end])
                if m:
                    ent=m.group(0)
                    decoded=None
                    body=m.group(1)
                    if body.startswith('#x') or body.startswith('#X'):
                        try: decoded=chr(int(body[2:],16))
                        except Exception: decoded=None
                    elif body.startswith('#'):
                        try: decoded=chr(int(body[1:]))
                        except Exception: decoded=None
                    else:
                        from html.entities import html5 as html5_entities
                        decoded=html5_entities.get(body+';') or html5_entities.get(body)
                    if decoded is not None:
                        out.append(html_escape_attr(decoded)); i+=len(ent); continue
                out.append('&amp;'); i+=1; continue
            # plain char
            out.append(html_escape_attr(c)); i+=1
        return ''.join(out)

    def _find_code_close(self,s,start,end,ticks):
        i=start
        while i<end:
            if s[i]=='`':
                j=i
                while j<end and s[j]=='`': j+=1
                if j-i==ticks:
                    return i
                i=j
            else:
                i+=1
        return -1

    def _trim_autolink(self, raw):
        # trim trailing punctuation like comrak autolink extension
        while raw and raw[-1] in '?!.,:;*_~\'"':
            raw=raw[:-1]
        # balanced parens: if trailing ) and more ) than (
        while raw.endswith(')') and raw.count(')')>raw.count('('):
            raw=raw[:-1]
        while raw.endswith(']') and raw.count(']')>raw.count('['):
            raw=raw[:-1]
        return raw

    def _try_parse_emphasis(self,s,i,end):
        c=s[i]
        # Count run
        j=i
        while j<end and s[j]==c: j+=1
        run=j-i
        # Underline: __ takes precedence as <u> (observed), not strong
        if c=='_' and run>=2:
            close=s.find('__', j, end)
            if close!=-1 and close>j:
                inner=self._parse_inline(s,j,close)
                return (f'<u>{inner}</u>', close+2)
            return None
        if c=='~':
            if run>=2:
                close=s.find('~~', j, end)
                if close!=-1 and close>j:
                    inner=self._parse_inline(s,j,close)
                    return (f'<del>{inner}</del>', close+2)
                return None
            else:
                close=s.find('~', j, end)
                # ensure closing not ~~ start? approximate
                if close!=-1 and close>j:
                    # avoid using closing that is part of ~~
                    if close+1<end and s[close+1]=='~':
                        return None
                    inner=self._parse_inline(s,j,close)
                    return (f'<del>{inner}</del>', close+1)
                return None
        # * or _
        # intraword underscore
        if c=='_' and i>0 and s[i-1].isalnum() and j<end and s[j].isalnum():
            return None
        if run>=3:
            close=s.find(c*3, j, end)
            if close!=-1 and close>j:
                inner=self._parse_inline(s,j,close)
                return (f'<em><strong>{inner}</strong></em>', close+3)
            # fall through to strong/em
        if run>=2:
            # strong with **
            # For '*' only; '_' handled above as underline
            close=s.find(c*2, j, end)
            if close!=-1 and close>j:
                # avoid empty / whitespace boundaries
                if s[j] not in ' \t\n' and s[close-1] not in ' \t\n':
                    inner=self._parse_inline(s,j,close)
                    return (f'<strong>{inner}</strong>', close+2)
            # if run >2 and no triple, maybe treat first? return None
            if run>2:
                return None
            # if no strong close, maybe try em with single (but ** could be empty?) return None
            return None
        # single
        # Find closing single not part of double (approx)
        k=j
        while k<end:
            if s[k]==c:
                # ensure not intraword underscore closing
                if c=='_' and k>0 and s[k-1].isalnum() and k+1<end and s[k+1].isalnum():
                    k+=1; continue
                if k>j and s[j] not in ' \t\n' and s[k-1] not in ' \t\n':
                    inner=self._parse_inline(s,j,k)
                    return (f'<em>{inner}</em>', k+1)
                else:
                    return None
            k+=1
        return None

    def _render_wikilink(self, inner):
        # comrak wikilinks title-after-pipe: [[title|url]] -> href=url, text=title; [[url]] -> href=url text=url
        if '|' in inner:
            title,url=inner.split('|',1)
            text=title; href=url
        else:
            text=inner; href=inner
        # comrak encodes spaces etc in href as %20 (observed later transformed)
        href_enc=urllib.parse.quote(href.strip(), safe="/-_.~")
        final=href_enc
        if self.link_rewriter:
            final=self.link_rewriter(href_enc, is_image=False, is_wikilink=True)
        else:
            final=href_enc
        # record links_to based on final slug handling in site postprocessing (wikilinks processed after page render)
        return f'<a href="{html_escape_attr(final)}" data-wikilink="true">{html_escape_attr(text.strip())}</a>'

    def _try_parse_link(self,s,i,end,is_image=False):
        start_bracket=i+1 if is_image else i
        # find matching ]
        depth=0; j=start_bracket
        while j<end:
            ch=s[j]
            if ch=='\\': j+=2; continue
            if ch=='`':
                # skip code span
                k=j
                while k<end and s[k]=='`': k+=1
                close=self._find_code_close(s,k,end,k-j)
                if close!=-1:
                    j=close+(k-j); continue
            if ch=='[': depth+=1
            elif ch==']':
                depth-=1
                if depth==0:
                    break
            j+=1
        if j>=end or depth!=0:
            return None
        text_start=start_bracket+1; text_end=j
        after=j+1
        dest=None; title=None
        # inline (dest ...)
        if after<end and s[after]=='(':
            # parse parenthesised, handling nested parens and <dest>
            k=after+1
            # skip whitespace/newlines
            while k<end and s[k] in ' \t\n': k+=1
            if k<end and s[k]=='<':
                close=s.find('>',k+1,end)
                if close==-1: return None
                dest=s[k+1:close]; k=close+1
            else:
                dstart=k; pdepth=0
                while k<end:
                    if s[k]=='\\': k+=2; continue
                    if s[k]=='(':
                        pdepth+=1
                    elif s[k]==')':
                        if pdepth==0: break
                        pdepth-=1
                    elif s[k] in ' \t\n' and pdepth==0:
                        break
                    k+=1
                dest=s[dstart:k]
            while k<end and s[k] in ' \t\n': k+=1
            if k<end and s[k] in '"\'':
                quote=s[k]; k+=1; tstart=k
                while k<end and s[k]!=quote:
                    if s[k]=='\\': k+=1
                    k+=1
                if k>=end: return None
                title=s[tstart:k]; k+=1
                while k<end and s[k] in ' \t\n': k+=1
            elif k<end and s[k]=='(':
                close=s.find(')',k+1,end)
                if close==-1: return None
                title=s[k+1:close]; k=close+1
                while k<end and s[k] in ' \t\n': k+=1
            if k<end and s[k]==')':
                after_all=k+1
            else:
                return None
            return self._make_link(s,text_start,text_end,dest,title,is_image), after_all
        # reference [label] or []
        if after<end and s[after]=='[':
            close=s.find(']', after+1, end)
            if close!=-1:
                label=s[after+1:close]
                if label.strip()=='':
                    label=s[text_start:text_end]
                key=_norm_ref_label(label)
                if key in self.refs:
                    dest,title=self.refs[key]
                    return self._make_link(s,text_start,text_end,dest,title,is_image), close+1
                else:
                    return None
        # shortcut reference
        label=s[text_start:text_end]
        # Don't treat as link if label looks like footnote handled earlier
        key=_norm_ref_label(label)
        if key in self.refs:
            dest,title=self.refs[key]
            return self._make_link(s,text_start,text_end,dest,title,is_image), after
        return None

    def _make_link(self,s,text_start,text_end,dest,title,is_image):
        raw_dest=dest or ''
        final=raw_dest
        if not is_image and self.link_rewriter:
            final=self.link_rewriter(raw_dest, is_image=False, is_wikilink=False)
        # images are not rewritten (observed)
        if is_image:
            alt_text=self._inline_plain_text(s[text_start:text_end])
            img=f'<img src="{html_escape_attr(final)}" alt="{html_escape_attr(alt_text)}"'
            if title:
                img+=f' title="{html_escape_attr(title)}"'
            img+=' />'
            if title:
                return f'<figure>{img}<figcaption>{html_escape_attr(title)}</figcaption></figure>'
            else:
                return f'<figure>{img}</figure>'
        else:
            inner=self._parse_inline(s,text_start,text_end)
            title_attr=f' title="{html_escape_attr(title)}"' if title else ''
            return f'<a href="{html_escape_attr(final)}"{title_attr}>{inner}</a>'

def _parse_link_title(s):
    s=s.strip()
    if len(s)>=2 and ((s[0]=='"' and s[-1]=='"') or (s[0]=="'" and s[-1]=="'") or (s[0]=='(' and s[-1]==')')):
        return s[1:-1]
    return None

def markdown_to_html(text, link_rewriter=None, headings_out=None):
    renderer=MarkdownRenderer()
    renderer.link_rewriter=link_rewriter
    html=renderer.render(text)
    if headings_out is not None:
        headings_out.extend(renderer.headings)
    return html, renderer

