                self.tokens.append(('name', m.group('name')))
            else:
                self.tokens.append(('op', m.group('op')))
        self.tokens.append(('eof',''))
        self.i=0
    def peek(self): return self.tokens[self.i]
    def next(self):
        t=self.tokens[self.i]; self.i+=1; return t
    def expect_op(self, op):
        t=self.next()
        if t!=('op',op): raise TemplateParseError(f"expected {op}, got {t}")
    def match_op(self, op):
        if self.peek()==('op',op): self.i+=1; return True
        return False
    def match_name(self, name):
        if self.peek()==('name',name): self.i+=1; return True
        return False
    def parse(self):
        node=self.parse_or()
        if self.peek()[0]!='eof':
            raise TemplateParseError(f"unexpected token {self.peek()}")
        return node
    def parse_or(self):
        node=self.parse_and()
        while self.match_name('or'):
            rhs=self.parse_and(); node=('or',node,rhs)
        return node
    def parse_and(self):
        node=self.parse_not()
        while self.match_name('and'):
            rhs=self.parse_not(); node=('and',node,rhs)
        return node
    def parse_not(self):
        if self.match_name('not'):
            return ('not', self.parse_not())
        return self.parse_cmp()
    def parse_cmp(self):
        node=self.parse_add()
        while True:
            if self.match_name('is'):
                neg=self.match_name('not')
                testtok=self.next()
                if testtok[0]!='name': raise TemplateParseError("expected test name")
                test=testtok[1]
                args=[]
                if self.match_op('('):
                    args=self._parse_call_args()
                node=('test', node, test, args, neg)
                continue
            if self.match_name('in'):
                rhs=self.parse_add(); node=('in',node,rhs); continue
            if self.peek()[0]=='op' and self.peek()[1] in ('==','!=','<','>','<=','>='):
                op=self.next()[1]; rhs=self.parse_add(); node=('cmp',op,node,rhs); continue
            break
        return node
    def parse_add(self):
        node=self.parse_mul()
        while self.peek()[0]=='op' and self.peek()[1] in ('+','-','~'):
            op=self.next()[1]; rhs=self.parse_mul()
            node=('concat',node,rhs) if op=='~' else ('bin',op,node,rhs)
        return node
    def parse_mul(self):
        node=self.parse_unary()
        while self.peek()[0]=='op' and self.peek()[1] in ('*','/','%'):
            op=self.next()[1]; rhs=self.parse_unary(); node=('bin',op,node,rhs)
        return node
    def parse_unary(self):
        if self.match_op('-'):
            return ('neg', self.parse_unary())
        return self.parse_postfix()
    def _parse_call_args(self):
        # opening ( already consumed; parse until )
        args=[]; kwargs={}
        if self.match_op(')'):
            return (args,kwargs)
        while True:
            # kwarg name = expr, but careful == token separate. Lookahead name and single '='
            if self.peek()[0]=='name' and self.i+1 < len(self.tokens) and self.tokens[self.i+1]==('op','='):
                kname=self.next()[1]; self.next() # =
                kwargs[kname]=self.parse_or()
            else:
                args.append(self.parse_or())
            if self.match_op(','):
                continue
            self.expect_op(')')
            break
        return (args,kwargs)
    def parse_postfix(self):
        node=self.parse_primary()
        while True:
            if self.match_op('.'):
                # attr name or number
                tok=self.next()
                if tok[0]=='name':
                    node=('attr',node,tok[1])
                elif tok[0]=='num':
                    node=('index',node,('lit',int(tok[1])))
                else:
                    raise TemplateParseError("expected attribute")
                continue
            if self.match_op('['):
                idx=self.parse_or(); self.expect_op(']'); node=('index',node,idx); continue
            if self.match_op('|'):
                tok=self.next()
                if tok[0]!='name': raise TemplateParseError("expected filter")
                fname=tok[1]; args=([],{})
                if self.match_op('('):
                    args=self._parse_call_args()
                node=('filter',node,fname,args); continue
            break
        return node
    def parse_primary(self):
        tok=self.next()
        if tok[0]=='str':
            raw=tok[1]
            if raw[0]=='"':
                try: val=json.loads(raw)
                except Exception:
                    val=raw[1:-1].replace('\\"','"').replace('\\n','\n').replace('\\t','\t').replace('\\\\','\\')
            else:
                val=raw[1:-1].replace("\\'","'").replace('\\n','\n').replace('\\t','\t').replace('\\\\','\\')
            return ('lit',val)
        if tok[0]=='num':
            return ('lit', float(tok[1]) if '.' in tok[1] else int(tok[1]))
        if tok[0]=='name':
            name=tok[1]
            if name=='true': return ('lit',True)
            if name=='false': return ('lit',False)
            # macro call namespace::name(...)
            if self.match_op('::'):
                mtok=self.next()
                if mtok[0]!='name': raise TemplateParseError("expected macro name")
                self.expect_op('('); args=self._parse_call_args()
                return ('macrocall', name, mtok[1], args)
            # function call
            if self.peek()==('op','('):
                self.next(); args=self._parse_call_args()
                return ('call', name, args)
            return ('var',name)
        if tok==('op','('):
            node=self.parse_or(); self.expect_op(')'); return node
        if tok==('op','['):
            elems=[]
            if self.match_op(']'):
                return ('array', elems)
            while True:
                elems.append(self.parse_or())
                if self.match_op(','): continue
                self.expect_op(']'); break
            return ('array',elems)
        raise TemplateParseError(f"unexpected token {tok}")

def _parse_expr(text):
    return ExprParser(text).parse()

class TeraEngine:
    def __init__(self):
        self.templates={}  # name -> dict(nodes, extends, blocks, imports, macros)
        self.functions={}
        self.default_date_format="%b %e, %Y"
        self._parse_cache={}
    def add_template(self, name, source):
        tpl=self._parse_template(name, source)
        self.templates[name]=tpl
        return tpl
    def _parse_template(self, name, source):
        tokens=_tera_tokenize(source)
        nodes, idx, stop = self._parse_nodes(tokens,0,stop_tags=set())
        extends=None; blocks={}; imports={}; macros={}
        for node in nodes:
            if node[0]=='extends': extends=node[1]
            elif node[0]=='block': blocks[node[1]]=node
            elif node[0]=='import': imports[node[2]]=node[1]
            elif node[0]=='macro': macros[node[1]]=node
        return {"name":name,"nodes":nodes,"extends":extends,"blocks":blocks,"imports":imports,"macros":macros,"source":source}
    def _parse_nodes(self, tokens, i, stop_tags):
        nodes=[]
        while i < len(tokens):
            kind, content=tokens[i]
            if kind=='text':
                if content: nodes.append(('text',content))
                i+=1; continue
            if kind=='output':
                nodes.append(('output', _parse_expr(content), content)); i+=1; continue
            # tag
            tag=content.strip()
            head=tag.split(None,1)[0] if tag else ''
            if head in stop_tags:
                return nodes,i,head
            if head=='if':
                expr=_parse_expr(tag[2:].strip())
                branches=[]; else_body=None
                body,i2,stop=self._parse_nodes(tokens,i+1,{'elif','else','endif'})
                branches.append((expr,body)); i=i2
                while True:
                    if i>=len(tokens): raise TemplateParseError("unclosed if")
                    stag=tokens[i][1].strip(); shead=stag.split(None,1)[0]
                    if shead=='elif':
                        e=_parse_expr(stag[4:].strip())
                        body,i,stop=self._parse_nodes(tokens,i+1,{'elif','else','endif'})
                        branches.append((e,body)); continue
                    if shead=='else':
                        else_body,i,stop=self._parse_nodes(tokens,i+1,{'endif'})
                        if i>=len(tokens): raise TemplateParseError("unclosed if")
                        i+=1; break
                    if shead=='endif':
                        i+=1; break
                    raise TemplateParseError("expected endif")
                nodes.append(('if',branches,else_body)); continue
            if head=='for':
                m=re.match(r'for\s+(.+?)\s+in\s+(.+)$', tag, re.S)
                if not m: raise TemplateParseError("bad for")
                vars_part=m.group(1).strip(); expr=_parse_expr(m.group(2).strip())
                varnames=[v.strip() for v in vars_part.split(',')]
                body,i2,stop=self._parse_nodes(tokens,i+1,{'else','endfor'})
                else_body=None; i=i2
                if i<len(tokens) and tokens[i][1].strip().split(None,1)[0]=='else':
                    else_body,i,stop=self._parse_nodes(tokens,i+1,{'endfor'})
                if i>=len(tokens): raise TemplateParseError("unclosed for")
                i+=1
                nodes.append(('for',varnames,expr,body,else_body)); continue
            if head=='set' or head=='set_global':
                rest=tag[len(head):].strip()
                m=re.match(r'([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.+)$', rest, re.S)
                if not m: raise TemplateParseError("bad set")
                nodes.append(('set',m.group(1),_parse_expr(m.group(2)))); i+=1; continue
            if head=='include':
                m=re.search(r'''["\']([^"\']+)["\']''', tag)
                if not m: raise TemplateParseError("bad include")
                ignore='ignore missing' in tag
                nodes.append(('include',m.group(1),ignore)); i+=1; continue
            if head=='extends':
                m=re.search(r'''["\']([^"\']+)["\']''', tag)
                nodes.append(('extends',m.group(1) if m else '')); i+=1; continue
            if head=='block':
                parts=tag.split()
                if len(parts)<2: raise TemplateParseError("bad block")
                bname=parts[1]
                body,i2,stop=self._parse_nodes(tokens,i+1,{'endblock'})
                if i2>=len(tokens): raise TemplateParseError("unclosed block")
                i=i2+1; nodes.append(('block',bname,body)); continue
            if head=='macro':
                m=re.match(r'macro\s+([A-Za-z_][A-Za-z0-9_]*)\s*\((.*)\)\s*$', tag, re.S)
                if not m: raise TemplateParseError("bad macro")
                mname=m.group(1); params=[]
                param_src=m.group(2).strip()
                if param_src:
                    # split by commas not in strings/brackets
                    for part in _split_top_commas(param_src):
                        if '=' in part:
                            pname,defexpr=part.split('=',1); params.append((pname.strip(),_parse_expr(defexpr.strip())))
                        else:
                            params.append((part.strip(),None))
                body,i2,stop=self._parse_nodes(tokens,i+1,{'endmacro'})
                if i2>=len(tokens): raise TemplateParseError("unclosed macro")
                i=i2+1; nodes.append(('macro',mname,params,body)); continue
            if head=='import':
                m=re.search(r'''["\']([^"\']+)["\']\s+as\s+([A-Za-z_][A-Za-z0-9_]*)''', tag)
                if not m: raise TemplateParseError("bad import")
                nodes.append(('import',m.group(1),m.group(2))); i+=1; continue
            if head=='break':
                nodes.append(('break',)); i+=1; continue
            if head=='continue':
                nodes.append(('continue',)); i+=1; continue
            if head=='raw':
                # collect text until endraw token (tokens already parsed, raw content may have been tokenized; approximation reconstruct)
                raw_parts=[]; i+=1
                while i < len(tokens):
                    if tokens[i][0]=='tag' and tokens[i][1].strip().split(None,1)[0]=='endraw':
                        i+=1; break
                    raw_parts.append(tokens[i][1]); i+=1
                nodes.append(('text',''.join(raw_parts))); continue
            if head in ('elif','else','endif','endfor','endblock','endmacro','endraw'):
                return nodes,i,head
            raise TemplateParseError(f"unknown tag {head}")
        return nodes,i,None

    # ---- rendering ----
    def render(self, template_name, context):
        if template_name not in self.templates:
            raise TemplateRenderError(f"Template '{template_name}' not found")
        frames=[dict(context), {}]  # global, set-locals
        return self._render_template(template_name, frames, chain=None)
    def render_string(self, source, context, name="__tera_one_off"):
        tpl=self._parse_template(name, source)
        old=self.templates.get(name)
        self.templates[name]=tpl
        try:
            frames=[dict(context), {}]
            return self._render_template(name, frames, chain=None)
        finally:
            if old is not None:
                self.templates[name]=old
            else:
                self.templates.pop(name,None)
    def _get_chain(self, template_name):
        chain=[]; seen=set(); cur=template_name
        while cur:
            if cur in seen: break
            seen.add(cur)
            tpl=self.templates.get(cur)
            if tpl is None:
                raise TemplateRenderError(f"Template '{cur}' not found")
            chain.append(tpl); cur=tpl.get('extends')
        return chain
    def _render_template(self, template_name, frames, chain=None):
        chain=self._get_chain(template_name)
        base=chain[-1]
        # imports/macros from all templates in chain available
        return self._render_nodes(base['nodes'], frames, chain, current_template=base, block_stack=[])
    def _render_nodes(self, nodes, frames, chain, current_template, block_stack):
        out=[]
        for node in nodes:
            typ=node[0]
            if typ=='text': out.append(node[1])
            elif typ=='output':
                val=self._eval(node[1], frames, chain, current_template, block_stack, in_output=True)
                if isinstance(val, Undefined):
                    raise TemplateRenderError(f"Variable `{val.path}` not found in context while rendering '{current_template['name']}'", var=val.path)
                out.append(self._to_string(val))
            elif typ=='if':
                done=False
                for expr,body in node[1]:
                    v=self._eval(expr, frames, chain, current_template, block_stack)
                    if self._truthy(v):
                        out.append(self._render_nodes(body,frames,chain,current_template,block_stack)); done=True; break
                if not done and node[2] is not None:
                    out.append(self._render_nodes(node[2],frames,chain,current_template,block_stack))
            elif typ=='for':
                out.append(self._render_for(node,frames,chain,current_template,block_stack))
            elif typ=='set':
                val=self._eval(node[2], frames, chain, current_template, block_stack)
                if isinstance(val, Undefined):
                    val=None
                frames[1][node[1]]=val
            elif typ=='include':
                inc_name=node[1]
                if inc_name not in self.templates:
                    if node[2]: continue
                    raise TemplateRenderError(f"Template '{inc_name}' not found")
                # includes render with current frames plus new set-locals frame? Share set locals so loop vars visible.
                # Push a shallow copy frame for sets inside include to not leak? Keep frames as is but save locals
                saved=dict(frames[1])
                try:
                    out.append(self._render_template(inc_name, frames))
                finally:
                    frames[1].clear(); frames[1].update(saved)
            elif typ=='block':
                # find most derived impl
                impls=[]
                for tpl in chain:
                    if node[1] in tpl['blocks']:
                        impls.append((tpl, tpl['blocks'][node[1]]))
                if not impls:
                    impls=[(current_template,node)]
                out.append(self._render_block_impl(impls,0,frames,chain,block_stack))
            elif typ=='break': raise BreakSignal()
            elif typ=='continue': raise ContinueSignal()
            elif typ in ('extends','import','macro'):
                continue
            else:
                continue
        return ''.join(out)
    def _render_block_impl(self, impls, idx, frames, chain, block_stack):
        tpl, node=impls[idx]
        # super callable via a special frame variable __super_<block>
        block_name=node[1]
        # Push info for super()
        frames.append({"__block_impls__":impls,"__block_idx__":idx,"__block_chain__":chain})
        try:
            return self._render_nodes(node[2], frames, chain, tpl, block_stack+[(impls,idx)])
        finally:
            frames.pop()
    def _render_for(self,node,frames,chain,current_template,block_stack):
        _, varnames, expr, body, else_body=node
        val=self._eval(expr, frames, chain, current_template, block_stack)
        items=[]
        if isinstance(val, Undefined) or val is None:
            items=[]
        elif isinstance(val, dict):
            items=list(val.items())
        elif isinstance(val,(list,tuple)):
            items=list(val)
        elif isinstance(val,str):
            items=list(val)
        else:
            items=[]
        if not items:
            if else_body is not None:
                return self._render_nodes(else_body,frames,chain,current_template,block_stack)
            return ""
        out=[]
        total=len(items)
        for idx,item in enumerate(items):
            frame={}
            if len(varnames)==1:
                frame[varnames[0]]=item
            else:
                # unpack
                if isinstance(item,(list,tuple)):
                    for vi,vn in enumerate(varnames):
                        frame[vn]=item[vi] if vi < len(item) else None
                elif isinstance(item,dict):
                    vals=list(item.values())
                    for vi,vn in enumerate(varnames):
                        frame[vn]=vals[vi] if vi < len(vals) else None
                else:
                    frame[varnames[0]]=item
                    for vn in varnames[1:]: frame[vn]=None
            frame['loop']={'index':idx+1,'index0':idx,'first':idx==0,'last':idx==total-1,'length':total}
            frames.append(frame)
            try:
                out.append(self._render_nodes(body,frames,chain,current_template,block_stack))
            except ContinueSignal:
                pass
            except BreakSignal:
                frames.pop(); break
            frames.pop()
        return ''.join(out)

    def _truthy(self,v):
        if isinstance(v,Undefined) or v is None: return False
        if isinstance(v,bool): return v
        if isinstance(v,(int,float)): return v!=0
        if isinstance(v,str): return len(v)>0
        if isinstance(v,(list,tuple,dict)): return len(v)>0
        return True
    def _to_string(self,v):
        if v is None or isinstance(v,Undefined): return ""
        if isinstance(v,bool): return "true" if v else "false"
        if isinstance(v,datetime): return v.strftime("%Y-%m-%dT%H:%M:%S")
        if isinstance(v,float):
            if v==int(v): return str(int(v))
            return ('%f'%v).rstrip('0').rstrip('.') if '.' in ('%f'%v) else str(v)
        if isinstance(v,(list,tuple,dict)):
            return json.dumps(_jsonable(v), ensure_ascii=False, separators=(',',':'))
        return str(v)
    def _lookup(self, name, frames):
        for fr in reversed(frames):
            if name in fr:
                return fr[name]
        return Undefined(name)
    def _eval(self, node, frames, chain=None, current_template=None, block_stack=None, in_output=False):
        if block_stack is None: block_stack=[]
        typ=node[0]
        if typ=='lit': return node[1]
        if typ=='array': return [self._eval(e,frames,chain,current_template,block_stack) for e in node[1]]
        if typ=='var': return self._lookup(node[1],frames)
        if typ=='attr':
            base=self._eval(node[1],frames,chain,current_template,block_stack)
            path=self._expr_path(node)
            if isinstance(base,Undefined): return Undefined(path)
            if base is None: return Undefined(path)
            attr=node[2]
            if isinstance(base,dict):
                return base.get(attr, Undefined(path))
            if isinstance(base,(list,tuple)) and attr.isdigit():
                idx=int(attr); return base[idx] if idx < len(base) else Undefined(path)
            # datetime attrs not used
            return Undefined(path)
        if typ=='index':
            base=self._eval(node[1],frames,chain,current_template,block_stack)
            idxv=self._eval(node[2],frames,chain,current_template,block_stack)
            path=self._expr_path(node)
            if isinstance(base,Undefined) or base is None or isinstance(idxv,Undefined): return Undefined(path)
            try:
                if isinstance(base,dict): return base.get(idxv, Undefined(path))
                if isinstance(base,(list,tuple,str)):
                    return base[int(idxv)]
            except Exception:
                return Undefined(path)
            return Undefined(path)
        if typ=='not':
            return not self._truthy(self._eval(node[1],frames,chain,current_template,block_stack))
        if typ=='neg':
            v=self._eval(node[1],frames,chain,current_template,block_stack); return -v if isinstance(v,(int,float)) else 0
        if typ=='and':
            left=self._eval(node[1],frames,chain,current_template,block_stack)
            if not self._truthy(left): return False
            return self._truthy(self._eval(node[2],frames,chain,current_template,block_stack))
        if typ=='or':
            left=self._eval(node[1],frames,chain,current_template,block_stack)
            if self._truthy(left): return True
            return self._truthy(self._eval(node[2],frames,chain,current_template,block_stack))
        if typ=='concat':
            l=self._eval(node[1],frames,chain,current_template,block_stack); r=self._eval(node[2],frames,chain,current_template,block_stack)
            if isinstance(l,Undefined): l=""
            if isinstance(r,Undefined): r=""
            return self._to_string(l)+self._to_string(r)
        if typ=='bin':
            op=node[1]; l=self._eval(node[2],frames,chain,current_template,block_stack); r=self._eval(node[3],frames,chain,current_template,block_stack)
            if isinstance(l,Undefined): l=0
            if isinstance(r,Undefined): r=0
            try:
                if op=='+': return l+r
                if op=='-': return l-r
                if op=='*': return l*r
                if op=='/': return l/r if r!=0 else 0
                if op=='%': return l%r
            except Exception:
                return 0
        if typ=='cmp':
            op=node[1]; l=self._eval(node[2],frames,chain,current_template,block_stack); r=self._eval(node[3],frames,chain,current_template,block_stack)
            if isinstance(l,Undefined): l=None
            if isinstance(r,Undefined): r=None
            try:
                if op=='==': return l==r
                if op=='!=': return l!=r
                if op=='<': return l<r
                if op=='>': return l>r
                if op=='<=': return l<=r
                if op=='>=': return l>=r
            except Exception:
                return False
        if typ=='in':
            l=self._eval(node[1],frames,chain,current_template,block_stack); r=self._eval(node[2],frames,chain,current_template,block_stack)
            if isinstance(l,Undefined) or isinstance(r,Undefined) or r is None: return False
            try:
                if isinstance(r,dict): return l in r
                if isinstance(r,(list,tuple)): return any(l==x or (isinstance(l,dict) and isinstance(x,dict) and l.get('slug')==x.get('slug') and l.get('slug') is not None) for x in r) if not isinstance(l,(str,int,float,bool)) else l in r
                return l in r
            except Exception:
                return False
        if typ=='test':
            _, expr, test, args, neg=node
            v=self._eval(expr,frames,chain,current_template,block_stack)
            result=self._apply_test(v,test,args,frames,chain,current_template,block_stack)
            return (not result) if neg else result
        if typ=='filter':
            _, expr, fname, args=node
            v=self._eval(expr,frames,chain,current_template,block_stack)
            argsv,kwargsv=self._eval_call_args(args,frames,chain,current_template,block_stack)
            return self._apply_filter(v,fname,argsv,kwargsv,frames,current_template)
        if typ=='call':
            fname=node[1]; args=node[2]
            if fname=='super':
                # find block impls in frames
                for fr in reversed(frames):
                    if '__block_impls__' in fr:
                        impls=fr['__block_impls__']; idx=fr['__block_idx__']; ch=fr['__block_chain__']
                        if idx+1 < len(impls):
                            return SafeString(self._render_block_impl(impls,idx+1,frames,ch,block_stack))
                        return SafeString("")
                return SafeString("")
            argsv,kwargsv=self._eval_call_args(args,frames,chain,current_template,block_stack)
            fn=self.functions.get(fname)
            if fn is None:
                raise TemplateRenderError(f"Function `{fname}` not found")
            return fn(argsv,kwargsv,frames,self)
        if typ=='macrocall':
            _, namespace, mname, args=node
            argsv,kwargsv=self._eval_call_args(args,frames,chain,current_template,block_stack)
            return SafeString(self._call_macro(namespace,mname,argsv,kwargsv,frames,chain,current_template))
        return None
    def _eval_call_args(self,args,frames,chain,current_template,block_stack):
        (pos,kw)=args
        return ([self._eval(e,frames,chain,current_template,block_stack) for e in pos],
                {k:self._eval(v,frames,chain,current_template,block_stack) for k,v in kw.items()})
    def _expr_path(self,node):
        if node[0]=='var': return node[1]
        if node[0]=='attr': return self._expr_path(node[1])+"."+node[2]
        if node[0]=='index': return self._expr_path(node[1])+"[...]"
        return "variable"
    def _apply_test(self,v,test,args,frames,chain,current_template,block_stack):
        argsv,kwargsv=self._eval_call_args(args,frames,chain,current_template,block_stack) if args else ([],{})
        first=argsv[0] if argsv else (list(kwargsv.values())[0] if kwargsv else None)
        if test=='defined': return not isinstance(v,Undefined)
        if test=='undefined': return isinstance(v,Undefined)
        if test=='string': return isinstance(v,str)
        if test=='number': return isinstance(v,(int,float)) and not isinstance(v,bool)
        if test=='starting_with': return isinstance(v,str) and isinstance(first,str) and v.startswith(first)
        if test=='ending_with': return isinstance(v,str) and isinstance(first,str) and v.endswith(first)
        if test=='containing':
            try: return first in v
            except Exception: return False
        if test=='odd': return isinstance(v,int) and v%2==1
        if test=='even': return isinstance(v,int) and v%2==0
        if test=='iterable': return isinstance(v,(list,tuple,dict))
        if test=='object': return isinstance(v,dict)
        return False
    def _call_macro(self, namespace, mname, argsv, kwargsv, frames, chain, current_template):
        # resolve macro template
        macro_tpl=None; macro_node=None
        # Search imports in chain templates and current template
        candidates=[]
        if chain: candidates.extend(chain)
        if current_template and current_template not in candidates: candidates.insert(0,current_template)
        # Also one-off template in templates dict may have imports
        for tpl in list(self.templates.values()):
            if tpl not in candidates:
                candidates.append(tpl)
        for tpl in candidates:
            imp=tpl.get('imports',{}).get(namespace)
            if imp and imp in self.templates:
                mt=self.templates[imp]
                if mname in mt.get('macros',{}):
                    macro_tpl=mt; macro_node=mt['macros'][mname]; break
            if namespace=='self' and mname in tpl.get('macros',{}):
                macro_tpl=tpl; macro_node=tpl['macros'][mname]; break
        if macro_node is None:
            raise TemplateRenderError(f"Macro `{namespace}::{mname}` not found")
        _, _mname, params, body=macro_node
        frame={}
        for idx,(pname,defexpr) in enumerate(params):
            if idx < len(argsv):
                frame[pname]=argsv[idx]
            elif pname in kwargsv:
                frame[pname]=kwargsv[pname]
            elif defexpr is not None:
                frame[pname]=self._eval(defexpr,frames,chain,current_template,[])
            else:
                raise TemplateRenderError(f"Macro `{mname}` is missing required argument `{pname}`")
        # Unknown kwargs in Tera cause error: mimic for custom/embedded error paths by raising if extra kw not in params
        param_names={p for p,_ in params}
        for k in kwargsv:
            if k not in param_names:
                raise TemplateRenderError(f"Macro `{mname}` received unknown argument `{k}`")
        frames.append(frame)
        try:
            return self._render_nodes(body,frames,chain,macro_tpl,[])
        finally:
            frames.pop()
    def _apply_filter(self,v,fname,argsv,kwargsv,frames,current_template):
        if fname=='default':
            if isinstance(v,Undefined) or v is None:
                return kwargsv.get('value', argsv[0] if argsv else None)
            return v
        if isinstance(v,Undefined):
            raise TemplateRenderError(f"Variable `{v.path}` not found in context while rendering '{current_template['name'] if current_template else ''}'", var=v.path)
        # helpers
        def kw(name, default=None, idx=None):
            if name in kwargsv: return kwargsv[name]
            if idx is not None and idx < len(argsv): return argsv[idx]
            return default
        if fname=='safe': return v
        if fname in ('escape','escape_xml'): return html_escape_attr(self._to_string(v))
        if fname=='slugify': return slugify(v)
        if fname=='trim': return str(v).strip(kw('pat',None,0)) if kw('pat',None,0) else str(v).strip()
        if fname=='trim_start': return str(v).lstrip()
        if fname=='trim_end': return str(v).rstrip()
        if fname=='trim_start_matches':
            pat=kw('pat','',0); s=str(v)
            if isinstance(pat,Undefined) or pat is None: pat=''
            pat=str(pat)
            if pat=='' :
                return s
            while s.startswith(pat):
                s=s[len(pat):]
            return s
        if fname=='trim_end_matches':
            pat=kw('pat','',0); s=str(v); pat=str(pat or '')
            if pat:
                while s.endswith(pat): s=s[:-len(pat)]
            return s
        if fname=='replace':
            frm=kw('from','',0); to=kw('to','',1); return str(v).replace(str(frm),str(to))
        if fname=='truncate':
            length=int(kw('length',255,0)); end=str(kw('end','…',1))
            s=str(v)
            if len(s) <= length: return s
            if length <= len(end): return end[:length]
            return s[:length-len(end)]+end
        if fname=='length':
            try: return len(v)
            except Exception: return 0
        if fname=='date':
            fmt=str(kw('format','%Y-%m-%d',0))
            dt=self._coerce_date(v)
            return chrono_format(dt,fmt) if dt else ""
        if fname=='default_date_format':
            dt=self._coerce_date(v)
            fmt=self.default_date_format
            # if site in context has different format, engine attr is set at site creation. Keep.
            return chrono_format(dt,fmt) if dt else ""
        if fname=='slice':
            start=kw('start',None,0); end=kw('end',None,1)
            if isinstance(v,(list,tuple,str)):
                return v[int(start) if start is not None else None:int(end) if end is not None else None]
            return v
        if fname=='sort':
            attr=kw('attribute',None,0)
            if isinstance(v,list):
                if attr:
                    def keyfn(x):
                        val=x.get(attr) if isinstance(x,dict) else None
                        return (val is None, val)
                    return sorted(v,key=keyfn)
                try: return sorted(v)
                except Exception: return list(v)
            return v
        if fname=='reverse':
            if isinstance(v,list): return list(reversed(v))
            if isinstance(v,str): return v[::-1]
            return v
        if fname=='split':
            pat=kw('pat',' ',0); 
            if pat is None or isinstance(pat,Undefined): pat=' '
            return str(v).split(str(pat))
        if fname=='round':
            method=str(kw('method','common',0)); prec=int(kw('precision',0,1))
            try:
                x=float(v)
            except Exception:
                return 0
            factor=10**prec
            if method=='ceil': return math.ceil(x*factor)/factor
            if method=='floor': return math.floor(x*factor)/factor
            return round(x,prec)
        if fname=='striptags': return strip_tags(v)
        if fname=='capitalize':
            s=str(v); return s[:1].upper()+s[1:].lower() if s else s
        if fname=='upper': return str(v).upper()
        if fname=='lower': return str(v).lower()
        if fname=='title': return str(v).title()
        if fname=='join':
            sep=str(kw('sep','',0))
            if isinstance(v,(list,tuple)): return sep.join(self._to_string(x) for x in v)
            return str(v)
        if fname=='first': return v[0] if isinstance(v,(list,tuple,str)) and len(v)>0 else None
        if fname=='last': return v[-1] if isinstance(v,(list,tuple,str)) and len(v)>0 else None
        if fname=='json_encode':
            pretty=kw('pretty',False,0)
            data=_tera_jsonable(v)
            if pretty:
                return json.dumps(data, ensure_ascii=False, indent=2)
            return json.dumps(data, ensure_ascii=False, separators=(',',':'))
        if fname=='urlencode': return urllib.parse.quote(str(v), safe='')
        if fname=='urlencode_strict': return urllib.parse.quote(str(v), safe='')
        if fname=='wordcount': return len(str(v).split())
        if fname=='int':
            try: return int(float(v))
            except Exception: return kw('default',0)
        if fname=='float':
            try: return float(v)
            except Exception: return kw('default',0.0)
        if fname=='as_str': return self._to_string(v)
        if fname=='concat':
            other=argsv[0] if argsv else kwargsv.get('with')
            if isinstance(v,list) and isinstance(other,list): return v+other
            return str(v)+str(other)
        if fname=='map':
            attr=kw('attribute',None,0)
            if isinstance(v,list) and attr: return [x.get(attr) if isinstance(x,dict) else None for x in v]
            return v
        if fname=='filter':
            attr=kw('attribute',None,0); val=kw('value',None,1)
            if isinstance(v,list):
                return [x for x in v if (x.get(attr) if isinstance(x,dict) and attr else x)==val]
            return v
        if fname=='group_by':
            attr=kw('attribute',None,0); res={}
            if isinstance(v,list):
                for x in v:
                    k=x.get(attr) if isinstance(x,dict) else None; res.setdefault(str(k),[]).append(x)
            return res
        if fname=='get':
            key=kw('key',None,0); default=kw('default',None,1)
            if isinstance(v,dict): return v.get(key,default)
            if isinstance(v,(list,tuple)):
                try: return v[int(key)]
                except Exception: return default
            return default
        if fname=='spaceless':
            return re.sub(r'>\s+<','><',str(v)).strip()
        if fname=='linebreaksbr': return str(v).replace('\n','<br>')
        if fname=='filesizeformat': return str(v)
        if fname=='remove_draft':
            if isinstance(v,list):
                return [x for x in v if not (isinstance(x,dict) and x.get('stream')=='draft')]
            return v
        if fname=='addslashes': return str(v).replace('\\','\\\\').replace('"','\\"').replace("'","\\'")
        # unknown filter: Tera errors at parse/load, raise render
        raise TemplateRenderError(f"Filter `{fname}` not found")
    def _coerce_date(self,v):
        if isinstance(v,datetime): return v
        if isinstance(v,(int,float)): return datetime.utcfromtimestamp(v)
        if isinstance(v,str):
            for fmt in ("%Y-%m-%dT%H:%M:%S+00:00","%Y-%m-%dT%H:%M:%S","%Y-%m-%d %H:%M:%S","%Y-%m-%d %H:%M","%Y-%m-%d"):
                try: return datetime.strptime(v.strip(),fmt)
                except Exception: pass
        return None

def _split_top_commas(s):
    parts=[]; cur=''; depth=0; in_s=False; in_d=False
    for ch in s:
        if in_s:
            cur+=ch
            if ch=="'": in_s=False
        elif in_d:
            cur+=ch
            if ch=='"': in_d=False
        else:
            if ch=="'": in_s=True; cur+=ch
            elif ch=='"': in_d=True; cur+=ch
            elif ch in '([{' : depth+=1; cur+=ch
            elif ch in ')]}' : depth-=1; cur+=ch
            elif ch==',' and depth==0: parts.append(cur); cur=''
            else: cur+=ch
    if cur.strip(): parts.append(cur)
    return parts

def _tera_jsonable(v, depth=0):
    if isinstance(v,Undefined): return None
    if isinstance(v,datetime): return v.strftime("%Y-%m-%dT%H:%M:%S")
    if isinstance(v,dict):
        if depth>20: return None
        return {str(k):_tera_jsonable(val,depth+1) for k,val in v.items()}
    if isinstance(v,(list,tuple)):
        return [_tera_jsonable(x,depth+1) for x in v]
    return v

