            if v==int(v): return str(int(v))
            return ('%f'%v).rstrip('0').rstrip('.') if '.' in ('%f'%v) else str(v)
        if isinstance(v,(list,tuple,dict)):
            return json.dumps(_jsonable(v), ensure_ascii=False, separators=(',',':'))
        return str(v)
