        if test=='defined': return not isinstance(v,Undefined)
        if test=='undefined': return isinstance(v,Undefined)
        if test=='string': return isinstance(v,str)
        if test=='number': return isinstance(v,(int,float)) and not isinstance(v,bool)
        if test=='starting_with': return isinstance(v,str) and isinstance(first,str) and v.startswith(first)
        if test=='ending_with': return isinstance(v,str) and isinstance(first,str) and v.endswith(first)
        if test=='containing':
            try: return first in v
            except Exception: return False
        if test=='odd': return isinstance(v,int) and v%2==1
        if test=='even': return isinstance(v,int) and v%2==0
        if test=='iterable': return isinstance(v,(list,tuple,dict))
        if test=='object': return isinstance(v,dict)
