def _split_top_commas(s):
    parts=[]; cur=''; depth=0; in_s=False; in_d=False
    for ch in s:
        if in_s:
            cur+=ch
            if ch=="'": in_s=False
        elif in_d:
            cur+=ch
            if ch=='"': in_d=False
        else:
            if ch=="'": in_s=True; cur+=ch
            elif ch=='"': in_d=True; cur+=ch
            elif ch in '([{' : depth+=1; cur+=ch
            elif ch in ')]}' : depth-=1; cur+=ch
            elif ch==',' and depth==0: parts.append(cur); cur=''
            else: cur+=ch
    if cur.strip(): parts.append(cur)
    return parts

def _tera_jsonable(v, depth=0):
    if isinstance(v,Undefined): return None
    if isinstance(v,datetime): return v.strftime("%Y-%m-%dT%H:%M:%S")
    if isinstance(v,dict):
        if depth>20: return None
        return {str(k):_tera_jsonable(val,depth+1) for k,val in v.items()}
    if isinstance(v,(list,tuple)):
        return [_tera_jsonable(x,depth+1) for x in v]
    return v

