# ---------------- URLs / site helpers ----------------
def make_url_for(cfg):
    def url_for(path=None, abs_=False):
        if path is None or isinstance(path, Undefined):
            raise TemplateRenderError("Missing `path` argument")
        p=str(path)
        if p.startswith('http://') or p.startswith('https://'):
            return p
        stripped=p.lstrip('/')
        site_url=str(cfg.get('url') or '')
        if abs_:
            if not site_url:
                return '/' + stripped
            return site_url.rstrip('/') + '/' + stripped
        else:
            prefix=''
            if '://' in site_url:
                try:
                    parsed=urllib.parse.urlsplit(site_url)
                    prefix=parsed.path.rstrip('/')
                except Exception:
                    prefix=''
            return prefix + '/' + stripped
    return url_for

def get_base_url(cfg):
    url=str(cfg.get('url') or '')
    if '://' in url:
        return url.rstrip('/')
    proto='https' if cfg.get('https') is True else 'http'
    if not url:
        return f'{proto}://'
    return f"{proto}://{url.strip('/')}"

def _copy_tree_to(src_dir, dest_root, log_target="marmite::site"):
    # Rust helper copies directory `src_dir` into dest_root (result dest_root/<basename>/...)
    src_dir=Path(src_dir); dest_root=Path(dest_root)
    dest_dir=dest_root / src_dir.name
    for root, dirs, files in os.walk(src_dir):
        dirs.sort(); 
        for f in sorted(files):
            sp=Path(root)/f
            rel=sp.relative_to(src_dir)
            dp=dest_dir/rel
            dp.parent.mkdir(parents=True, exist_ok=True)
            shutil.copyfile(sp,dp)
    return dest_dir

def _write_file(path, data, log_generated=True, target="marmite::site"):
    path=Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    if isinstance(data, bytes):
        path.write_bytes(data)
    else:
        path.write_text(data, encoding='utf-8')
    if log_generated:
        log_info(target, f"Generated {path}")

def _extract_zip_b64_to(b64, dest_dir, log_each=True, target="marmite::embedded"):
    raw=base64.b64decode(b64)
    with zipfile.ZipFile(io.BytesIO(raw)) as z:
        # Order in embedded generation logs: order as zip entries sorted by name? Original embedded order specific:
        names=z.namelist()
        # Sort to match observed: Atkinson, avatar, colorschemes/* sorted, custom.css... essentially lexicographic with colorschemes before custom etc.
        for name in sorted(names):
            data=z.read(name)
            out=Path(dest_dir)/name
            out.parent.mkdir(parents=True, exist_ok=True)
            out.write_bytes(data)
            if log_each:
                log_info(target, f"Generated {out}")

def _zip_names_data(b64):
    raw=base64.b64decode(b64)
    with zipfile.ZipFile(io.BytesIO(raw)) as z:
        return [(name,z.read(name)) for name in z.namelist()]

