# ---------------- Content parsing ----------------
class FrontmatterError(Exception):
    def __init__(self, msg): self.msg=msg; super().__init__(msg)

def _yaml_value_to_slug_str(v):
    if v is None: return ""
    if isinstance(v,str): return v
    if isinstance(v,(list,tuple)): return '-'.join(_yaml_value_to_slug_str(x) for x in v)
    if isinstance(v,bool): return 'true' if v else 'false'
    if isinstance(v,dict): return '-'.join(_yaml_value_to_slug_str(x) for x in v.values())
    return str(v)

def _fm_list(v):
    if v is None: return []
    if isinstance(v,list):
        out=[]
        for x in v:
            if x is None: continue
            if isinstance(x,str):
                s=x.strip()
                if s: out.append(s)
            else:
                out.append(str(x).strip())
        return out
    if isinstance(v,str):
        return [p.strip() for p in v.split(',') if p.strip()!='']
    # scalar other
    return [str(v).strip()]

def _extract_frontmatter(raw_text):
    """Returns (fm dict or None, body text).

    Raises FrontmatterError for invalid front matter / YAML.
    """
    text=raw_text.replace('\r\n','\n').replace('\r','\n')
    # Marmite seems to allow leading whitespace/newlines before frontmatter
    stripped=text.lstrip(' \t\n')
    offset=len(text)-len(stripped)
    if not stripped.startswith('---'):
        return None, text
    # first line must be --- possibly with trailing spaces
    first_end=stripped.find('\n')
    if first_end==-1:
        raise FrontmatterError("Invalid front matter format")
    first_line=stripped[:first_end].strip()
    if first_line!='---':
        # If line is '----' etc, treat not as frontmatter (hr). But starts with --- and more dashes?
        return None, text
    rest=stripped[first_end+1:]
    # find closing line '---'
    lines=rest.split('\n')
    close_idx=None
    for idx,line in enumerate(lines):
        if line.strip()=='---':
            close_idx=idx; break
    if close_idx is None:
        raise FrontmatterError("Invalid front matter format")
    fm_text='\n'.join(lines[:close_idx])
    if fm_text.strip()=='':
        raise FrontmatterError("Invalid front matter format")
    try:
        parsed=parse_yaml(fm_text)
    except YamlError as e:
        # Message format seen: Failed to parse YAML: did not find expected key, while parsing a block mapping
        problem=e.problem
        context=e.context
        if context:
            raise FrontmatterError(f"Failed to parse YAML: {problem}, {context}")
        raise FrontmatterError(f"Failed to parse YAML: {problem}")
    if parsed is None:
        raise FrontmatterError("Invalid front matter format")
    if not isinstance(parsed, dict):
        raise FrontmatterError(f"Failed to parse YAML: invalid type: {_yaml_type_desc(parsed)}, expected a map")
    body='\n'.join(lines[close_idx+1:])
    return parsed, body

def _internal_link_rewriter(url, is_image=False, is_wikilink=False):
    if is_image:
        return url
    if url is None: return ''
    u=str(url)
    if u=='' or u.startswith('#') or u.startswith('./') or u.startswith('../'):
        return u
    if '://' in u or u.startswith('mailto:') or u.startswith('tel:'):
        return u
    # preserve known file extensions (non-html/md assets)
    # Split fragment/query
    frag=''
    if '#' in u:
        u, frag_part = u.split('#',1); frag='#'+frag_part
    if '?' in u:
        u=u.split('?',1)[0]
    # If path has a dot extension that is not .md/.html and looks like a file asset, keep original (incl fragment dropped? asset links observed kept as-is; recombine)
    # Determine extension of last segment
    last=u.rstrip('/').split('/')[-1] if u else ''
    if '.' in last:
        ext=last.rsplit('.',1)[-1]
        # common asset extensions keep
        if ext.lower() in ('png','jpg','jpeg','gif','svg','webp','ico','pdf','zip','txt','css','js','json','xml','rss','mp3','mp4','wav','ogg','webm','woff','woff2','ttf','eot','csv','md'.replace('md','never')):
            return u+frag
    stripped=u.lstrip('/')
    # strip .md / .html suffix case-sensitive
    if stripped.endswith('.md'):
        stripped=stripped[:-3]
    elif stripped.endswith('.html'):
        stripped=stripped[:-5]
    # slug-like flatten: slash, dots, spaces/%20 etc.
    # Wikilink href already quoted %20: observed Wiki Page -> wiki-20page : remove '%' then slugify retains 20 joined with dash?
    # For normal links, simple filenames slugify? FOO.MD -> foo-md ; foo is preserved. Underscores in links? likely slugify converts to -
    # But links to pages with filename slug containing spaces/caps (HELLO WORLD.html) - a link [x](HELLO WORLD.md) would slugify to hello-world (not actual slug) in reference also (they slugify file stem for internal links)
    slug=slugify(stripped.replace('/','-').replace('%','-'))
    # slugify removes underscores->-, but what about explicit link to file with underscore slug a_first.md -> a-first.html in reference? unknown, follow slugify hypothesis.
    return f"{slug}.html{frag}" if slug else u+frag

def _extract_links_to(html_text):
    links=[]
    for m in re.finditer(r'<a[^>]*\shref="([^"]*)"', html_text):
        href=html.unescape(m.group(1))
        if not href or href.startswith('#') or href.startswith('./') or href.startswith('../') or '://' in href or href.startswith('mailto:'):
            continue
        href_no_frag=href.split('#',1)[0]
        if href_no_frag.endswith('.html'):
            slug=href_no_frag.lstrip('/')[:-5]
            # If href had directories (raw html), keep full? Convert slash? Backlink compare uses slug equality; keep basename? reference extraction likely from markdown link slug (flattened). HTML rendered hrefs from markdown are already flattened.
            if '/' in slug:
                slug=slug.split('/')[-1] if False else slug
            links.append(slug)
    return links if links else None

def _build_toc(headings):
    if not headings:
        return ""
    out=[]
    base=headings[0][0]
    current=base
    out.append('<ul>')
    for level,text,anchor in headings:
        if level>current:
            for _ in range(level-current): out.append('<ul>')
        elif level<current:
            for _ in range(current-level): out.append('</ul>')
        current=level
        out.append(f'<li><a href="#{anchor}">{html_escape_text(text)}</a></li>')
    # close to base
    for _ in range(current-base): out.append('</ul>')
    out.append('</ul>')
    return '\n'.join(out)+'\n'

def parse_content_file(path, content_source_dir, cfg, md_header, md_footer, references):
    """Parse one markdown file into content dict (without backlinks/next/prev yet)."""
    path=Path(path)
    raw=path.read_text(encoding='utf-8')  # may raise UnicodeDecodeError/OSError handled caller
    fm, body = _extract_frontmatter(raw)
    if fm is None: fm={}
    # Title
    title=None
    body_for_md=body
    fm_title_present = 'title' in fm and isinstance(fm.get('title'), str)
    if fm_title_present:
        title=fm.get('title')
    else:
        # find first non-empty line
        lines=body.split('\n')
        found_idx=None; found_line=None
        for idx,line in enumerate(lines):
            if line.strip()!='':
                found_idx=idx; found_line=line; break
        if found_line is None:
            title=""
            body_for_md=""
        else:
            t=found_line.strip()
            # strip leading #'s and spaces
            t=re.sub(r'^#+\s*', '', t)
            title=t.strip()
            # remove the found line (and preceding blank lines effectively)
            body_for_md='\n'.join(lines[found_idx+1:])
    # filename date and stem
    stem=path.stem  # filename without .md
    filename_date=None; stem_rest=stem
    m_exact=re.fullmatch(r'(\d{4})-(\d{2})-(\d{2})', stem)
    if m_exact:
        try:
            filename_date=datetime(int(m_exact.group(1)),int(m_exact.group(2)),int(m_exact.group(3))); stem_rest=stem
        except Exception:
            filename_date=None; stem_rest=stem
    else:
        filename_date, stem_rest=parse_filename_date(stem)
    # date
    date_val=None
    fm_date=fm.get('date') if 'date' in fm else None
    if isinstance(fm_date,str) and fm_date.strip()!='':
        date_val=parse_date_value(fm_date, str(path))  # raises ContentDateError
    elif isinstance(fm_date, datetime):
        date_val=fm_date
    else:
        date_val=filename_date
    is_post=date_val is not None
    # stream
    stream_val=None
    if isinstance(fm.get('stream'), str):
        stream_val=fm.get('stream')
    elif is_post:
        stream_val="index"
    # slug base
    if 'slug' in fm and fm.get('slug') is not None:
        base_slug=slugify(_yaml_value_to_slug_str(fm.get('slug')))
    elif 'title' in fm and fm.get('title') is not None:
        base_slug=slugify(_yaml_value_to_slug_str(fm.get('title')))
    else:
        base_slug=stem_rest
