def _build_toc(headings):
    if not headings:
        return ""
    out=[]
    base=headings[0][0]
    current=base
    out.append('<ul>')
    for level,text,anchor in headings:
        if level>current:
            for _ in range(level-current): out.append('<ul>')
        elif level<current:
            for _ in range(current-level): out.append('</ul>')
        current=level
        out.append(f'<li><a href="#{anchor}">{html_escape_text(text)}</a></li>')
    # close to base
    for _ in range(current-base): out.append('</ul>')
    out.append('</ul>')
    return '\n'.join(out)+'\n'

