def shallow_content(c):
    copy={}
    for k in ["title","description","slug","html","tags","date","extra","links_to","back_links","card_image","banner_image","authors","stream","series","pinned","toc","modified_time","comments","next","previous","source_path"]:
        v=c.get(k)
