            copy[k]=list(v) if isinstance(v,list) else v
        elif k in ("next","previous"):
            copy[k]=None
        elif isinstance(v,list):
            copy[k]=list(v)
        elif isinstance(v,dict):
            copy[k]=dict(v)
        else:
            copy[k]=v
    return copy

