            for root, dirs, files in os.walk(self.content_dir):
                # Do not sort dirs to mimic readdir? But deterministic sorting is safer for tests.
                dirs.sort(); files_sorted=sorted(files)
                for f in files_sorted:
                    if f.endswith('.md'):
                        md_files.append(Path(root)/f)
        contents=[]
        seen_slugs={}
        for path in md_files:
            if path.name.startswith('_'):
                continue
            try:
                c=parse_content_file(path, self.content_dir, self.cfg, md_header, md_footer, references)
            except ContentDateError as e:
                log_error("marmite::content", f"ERROR: Invalid date format {e.val} when parsing {e.path}, premature end of input")
                raise SiteFatal(1)
            except FrontmatterError as e:
                log_error("marmite::site", f'Failed to process content: "{e.msg}"')
                continue
            except UnicodeDecodeError as e:
                log_error("marmite::site", f'Failed to process content: "{e}"')
                continue
            except OSError as e:
                log_error("marmite::site", f'Failed to process content: "{e}"')
                continue
            contents.append(c)
            slug=c.get('slug')
            if slug in seen_slugs:
                log_error("marmite::site", f"Duplicate slug found: '{slug}' - try setting `title` or `slug` as a unique text, or leave both empty so filename will be assumed. - The latest content rendered will overwrite the previous one.")
            else:
                seen_slugs[slug]=path
        # split posts/pages and strip internal
        posts=[]; pages=[]
        for c in contents:
            is_post=c.pop('_is_post', c.get('date') is not None)
            c.pop('_headings',None); c.pop('_raw_body',None)
            tc=template_content(c)
            # preserve reference for internal via slug map
            if is_post: posts.append(tc)
            else: pages.append(tc)
        # sort posts by date desc, stable
        posts_sorted=sorted(posts, key=lambda x: x.get('date') or datetime.min, reverse=True)
        # pages by title desc
        pages_sorted=sorted(pages, key=lambda x: str(x.get('title') or ''), reverse=True)
        self.contents=posts_sorted+pages_sorted  # not semantically used much
        self.posts=posts_sorted; self.pages=pages_sorted
        # backlinks: snapshots
        # First create base snapshots (without backlinks/next)
        base_snaps={id(c): shallow_content(c) for c in posts_sorted+pages_sorted}
        for c in base_snaps.values():
            c['back_links']=[]
        for target in posts_sorted+pages_sorted:
            bl=[]
            for src in posts_sorted+pages_sorted:
                lt=src.get('links_to') or []
                if target.get('slug') in lt:
                    bl.append(base_snaps[id(src)])
            target['back_links']=bl
        # next/prev for posts grouped by (stream, series)
        # Group posts in chronological asc order
        groups={}
        for p in posts_sorted:
            key=(p.get('stream'), p.get('series'))
            groups.setdefault(key,[]).append(p)
        for key, arr in groups.items():
            chrono=sorted(arr, key=lambda x: x.get('date') or datetime.min)
            for idx,p in enumerate(chrono):
                prev=chrono[idx-1] if idx>0 else None
                nxt=chrono[idx+1] if idx+1<len(chrono) else None
                p['previous']=shallow_content(prev) if prev else None
                if p['previous'] is not None:
                    # shallow copy's back_links should be snapshots list of prev's backlinks (as base snaps) to mimic nested json
                    p['previous']['back_links']=prev.get('back_links',[])
                p['next']=shallow_content(nxt) if nxt else None
                if p['next'] is not None:
                    p['next']['back_links']=nxt.get('back_links',[])
        # groups maps
        tag_map=self._build_group_map(posts_sorted, 'tag')
        author_map=self._build_group_map(posts_sorted, 'author')
        archive_map=self._build_group_map(posts_sorted, 'archive')
        stream_map=self._build_group_map(posts_sorted, 'stream')
        series_map=self._build_group_map(posts_sorted, 'series')
        self._group_maps={'tag':tag_map,'author':author_map,'archive':archive_map,'stream':stream_map,'series':series_map}
        cfg_json=config_for_json(self.cfg)
        self.site_data={
            "site":cfg_json,
            "posts":posts_sorted,
            "pages":pages_sorted,
            "tag":{"kind":"Tag","map":tag_map},
            "archive":{"kind":"Archive","map":archive_map},
            "author":{"kind":"Author","map":author_map},
            "stream":{"kind":"Stream","map":stream_map},
            "series":{"kind":"Series","map":series_map},
            "latest_timestamp":None,
            "config_path":str(self.cfg_path),
            "force_render":bool(self.force_render),
            "generated_urls":{},  # filled below
            "galleries":self.galleries,
        }
        self.generated_urls=self._compute_generated_urls()
        self.site_data["generated_urls"]=self.generated_urls
        # 404 content
        self._404_content=self._make_404_content(references)
        return self.site_data

    def _build_group_map(self, posts, kind):
        mp={}
        def push(key, content):
            if key is None: return
            key=str(key)
            mp.setdefault(key,[]).append(content)
            sl=slugify(key)
            if sl and sl!=key:
                mp.setdefault(sl,[]).append(content)
        for p in posts:
            if kind=='tag':
                for t in p.get('tags') or []: push(t,p)
            elif kind=='author':
                for a in p.get('authors') or []: push(a,p)
            elif kind=='archive':
                if p.get('date'): push(str(p['date'].year),p)
            elif kind=='stream':
                if p.get('stream'): push(p.get('stream'),p)
            elif kind=='series':
                if p.get('series'): push(p.get('series'),p)
        return mp

    def _make_404_content(self, references):
        p=self.content_dir/"_404.md"
        base={
            "title":"Page not found","description":None,"slug":"404","html":"Page not found :/","tags":[],"date":None,"extra":None,"links_to":None,"back_links":[],"card_image":None,"banner_image":None,"authors":[],"stream":None,"series":None,"pinned":False,"toc":None,"modified_time":None,"comments":None,"next":None,"previous":None,"source_path":None,
        }
        if not p.is_file():
            return base
        try:
            raw=p.read_text(encoding='utf-8')
        except Exception:
            return base
        try:
            fm, body=_extract_frontmatter(raw)
        except FrontmatterError:
            fm, body=None, raw
        if fm and isinstance(fm.get('title'),str):
            base['title']=fm['title']
            md_text=body
        else:
            # title from first non-empty line, body as original (after fm if present)
            src=body if fm is not None else raw
            for line in src.split('\n'):
                if line.strip()!='':
                    base['title']=re.sub(r'^#+\s*','',line.strip()).strip(); break
            md_text=src
        if references:
            md_text=md_text.rstrip('\n')+'\n\n'+references
        ht,_=markdown_to_html(md_text, link_rewriter=_internal_link_rewriter)
        base['html']=ht
        return base

    def _distinct_group_entities(self, kind):
        """Returns list of (raw_name, slug, items) for generation of individual group pages.
        Deduplicated by slug, items taken from slug key in map if present else raw.
        Raw name chosen as first original key with that slug (prefer non-slug original).
        """
        mp=self._group_maps.get(kind,{})
        # Determine original raw names from contents in order of posts list
        raw_names=[]
        for p in self.posts:
            vals=[]
            if kind=='tag': vals=p.get('tags') or []
            elif kind=='author': vals=p.get('authors') or []
            elif kind=='archive': vals=[str(p['date'].year)] if p.get('date') else []
            elif kind=='stream': vals=[p.get('stream')] if p.get('stream') else []
            elif kind=='series': vals=[p.get('series')] if p.get('series') else []
            for v in vals:
                if v is not None and str(v) not in raw_names:
                    raw_names.append(str(v))
        entities=[]; seen_slugs=set()
        for raw in raw_names:
            sl=slugify(raw) if kind!='archive' else raw
            if sl in seen_slugs: continue
            seen_slugs.add(sl)
            items=mp.get(sl, mp.get(raw,[]))
            # Deduplicate items preserving order (slug map may have duplicates due duplicate tags)
            uniq=[]; seen_ids=set()
            for it in items:
                if id(it) in seen_ids: continue
                seen_ids.add(id(it)); uniq.append(it)
            entities.append((raw,sl,uniq))
        return entities

    def _compute_generated_urls(self):
        # raw filenames (no leading slash / no url prefix)
        urls={"posts":[],"pages":[],"tags":[],"authors":[],"series":[],"streams":[],"archives":[],"feeds":[],"pagination":[],"file_mappings":[],"misc":[]}
        for p in self.posts:
            urls["posts"].append(f"{p['slug']}.html")
        for pg in self.pages:
            urls["pages"].append(f"{pg['slug']}.html")
        if self.pages:
            urls["pages"].append("pages.html")
        # tags
        tag_entities=self._distinct_group_entities('tag')
        for raw,sl,items in tag_entities:
            urls["tags"].append(f"tag-{sl}.html")
        if tag_entities:
            urls["tags"].append("tags.html")
        author_entities=self._distinct_group_entities('author')
        for raw,sl,items in author_entities:
            urls["authors"].append(f"author-{sl}.html")
        if author_entities:
            urls["authors"].append("authors.html")
        # series: reference iterates map keys (both raw and slug) causing duplicates when slug != raw. Replicate:
        series_map=self._group_maps.get('series',{})
        if series_map:
            for key in series_map.keys():
                sl=slugify(key)
                urls["series"].append(f"series-{sl}.html")
            urls["series"].append("series.html")
        # streams
        stream_entities=[e for e in self._distinct_group_entities('stream') if e[0]!="index"]
        for raw,sl,items in stream_entities:
            urls["streams"].append(f"{sl}.html")
        if self.posts:
            urls["streams"].append("streams.html")
        # archives
        archive_entities=self._distinct_group_entities('archive')
        for raw,sl,items in archive_entities:
            urls["archives"].append(f"archive-{raw}.html")
        if archive_entities:
            urls["archives"].append("archive.html")
        # feeds
        index_posts=[p for p in self.posts if p.get('stream')=="index"]
        if index_posts:
            urls["feeds"].append("index.rss")
        # Order in reference appears hashmap-ish; use generation order: streams, series(map keys), tags, authors, archives to match base_feeds template order? urls.json earlier: index, tag..., author, archive. And for stream case: draft.rss, index, news, archive (hash). We'll do deterministic: tag, author, archive, stream, series after index.
        for raw,sl,items in tag_entities:
            urls["feeds"].append(f"tag-{sl}.rss")
        for raw,sl,items in author_entities:
            urls["feeds"].append(f"author-{sl}.rss")
        for raw,sl,items in archive_entities:
            urls["feeds"].append(f"archive-{raw}.rss")
        for raw,sl,items in stream_entities:
            urls["feeds"].append(f"{sl}.rss")
        # series feeds replicate map-key duplication
        if series_map:
            for key in series_map.keys():
                urls["feeds"].append(f"series-{slugify(key)}.rss")
        if self.cfg.get('json_feed'):
            jf=[]
            if index_posts: jf.append("index.json")
            for raw,sl,items in tag_entities: jf.append(f"tag-{sl}.json")
            for raw,sl,items in author_entities: jf.append(f"author-{sl}.json")
            for raw,sl,items in archive_entities: jf.append(f"archive-{raw}.json")
            for raw,sl,items in stream_entities: jf.append(f"{sl}.json")
            if series_map:
                for key in series_map.keys(): jf.append(f"series-{slugify(key)}.json")
            urls["feeds"].extend(jf)
        # pagination
        pagination=int(self.cfg.get('pagination') or 10)
        def paginate_urls(slug, count):
            if count<=0: return []
            total=(count+pagination-1)//pagination if pagination else 1
            return [f"{slug}-{n}.html" for n in range(1,total+1)]
        if self.pages:
            urls["pagination"].extend(paginate_urls("pages", len(self.pages)))
        for raw,sl,items in tag_entities:
            urls["pagination"].extend(paginate_urls(f"tag-{sl}", len(items)))
        for raw,sl,items in author_entities:
            urls["pagination"].extend(paginate_urls(f"author-{sl}", len(items)))
        for raw,sl,items in archive_entities:
            urls["pagination"].extend(paginate_urls(f"archive-{raw}", len(items)))
        for raw,sl,items in stream_entities:
            urls["pagination"].extend(paginate_urls(f"{sl}", len(items)))
        if series_map:
            for key in series_map.keys():
                items=series_map[key]
                uniq=[]; seen=set()
                for it in items:
                    if id(it) in seen: continue
                    seen.add(id(it)); uniq.append(it)
                urls["pagination"].extend(paginate_urls(f"series-{slugify(key)}", len(uniq)))
        # index pagination only if total > 1 (observed)
        if index_posts:
            total=(len(index_posts)+pagination-1)//pagination if pagination else 1
            if total>1:
                urls["pagination"].extend([f"index-{n}.html" for n in range(1,total+1)])
        # file mappings (dest regardless existence)
        for fm in self.cfg.get('file_mapping') or []:
            if isinstance(fm,dict) and fm.get('dest'):
                urls["file_mappings"].append(str(fm['dest']))
        urls["misc"].append("index.html")
        return urls

    def urls_public(self):
        # transform generated raw filenames with url_for(abs=True)
        raw=self.generated_urls or self._compute_generated_urls()
