    def _make_thumbnail(self, src, dest):
        size=int(self.cfg.get('gallery_thumb_size') or 50)
        # PNG support pure python; for other formats copy original as fallback, but if file is fake/corrupt, emulate error log.
        try:
            data=Path(src).read_bytes()
        except Exception as e:
            log_error("marmite::gallery", f"Failed to create thumbnail for {src}: {e}")
            return False
        if data.startswith(b'\x89PNG'):
            try:
                w,h,pixels,mode=_png_decode_rgba(data)
                # resize to width=size (and height proportional; if portrait, height proportional to width may exceed? reference thumbnail for portrait? assume max dimension size preserving aspect by scaling longest side? For 200x100 size50 -> 50x25. For 10x10 -> 50x50. This fits width=size and maxdim both.
                scale=size/max(w,h) if max(w,h)>0 else 1
                # If image is landscape and they resize width exactly, same. Use width scaling if w>=h else height scaling = max dim.
                nw=max(1,round(w*scale)); nh=max(1,round(h*scale))
                resized=_resize_rgba_nearest(w,h,pixels,nw,nh)
                Path(dest).write_bytes(_png_encode_rgba(nw,nh,resized))
                return True
            except Exception as e:
                log_error("marmite::gallery", f"Failed to create thumbnail for {src}: Format error decoding Png: {e}")
                return False
        # Detect JPEG signature; pure copy fallback if valid SOI, can't decode. If fake, error message like reference.
        if src.suffix.lower() in ('.jpg','.jpeg'):
            if not data.startswith(b'\xff\xd8'):
                log_error("marmite::gallery", f"Failed to create thumbnail for {src}: Format error decoding Jpeg: I/O errors Generic I/O error: Cannot satisfy read")
                return False
            # copy as thumbnail (dimension may differ)
            try:
                Path(dest).write_bytes(data); return True
            except Exception:
                return False
        # Other format copy
        try:
            Path(dest).write_bytes(data); return True
        except Exception:
            return False

