            path=kwargs.get('path', args[0] if args else None)
            abs_=kwargs.get('abs', args[1] if len(args)>1 else False)
            if path is None or isinstance(path,Undefined):
                # Tera error style inner recognized by caller formatter
                raise TemplateRenderError("Missing `path` argument", var="__url_for_missing_path__")
