            kind=kwargs.get('kind', args[0] if args else '')
            mp=self._group_maps.get(str(kind),{})
            items=list(mp.items())
            # sort by count desc, stable insertion
            items.sort(key=lambda kv: len(kv[1]), reverse=True)
