    # ---- galleries ----
    def _process_galleries(self):
        log_info("marmite::gallery", f"Processing galleries from: {self.gallery_dir}")
        if not self.gallery_dir.is_dir():
            log_info("marmite::gallery", f"Gallery directory does not exist: {self.gallery_dir}")
            self.galleries={}
            return
        galleries={}
        count=0
        for sub in sorted([p for p in self.gallery_dir.iterdir() if p.is_dir()], key=lambda p:p.name):
            files=[]
            for root, dirs, fs in os.walk(sub):
                # skip thumbnails dir itself for files count? Reference in second runs would count thumb files in gallery dir recursive maybe.
                if 'thumbnails' in dirs and Path(root)==sub:
                    # keep thumbnails for media copy but don't count as gallery images? Original first run creates it after collecting.
                    pass
                for f in sorted(fs):
                    fp=Path(root)/f
                    if 'thumbnails' in fp.relative_to(sub).parts:
                        continue
                    files.append(fp)
            image_files=[f for f in files if f.suffix.lower() in ('.jpg','.jpeg','.png','.gif','.webp','.bmp','.tiff')]
            # reference counts files (seems image files) in gallery
            counted=image_files
            if self.cfg.get('gallery_create_thumbnails') and image_files:
                thumb_dir=sub/"thumbnails"
                try:
                    thumb_dir.mkdir(parents=True, exist_ok=True)
                except Exception:
                    pass
                for img in image_files:
                    out=thumb_dir/img.name
                    if not out.exists():
                        ok=self._make_thumbnail(img,out)
                        if ok:
                            log_info("marmite::gallery", f"Created thumbnail: {out}")
                    # else existing thumbnail log? none
            galleries[sub.name]={"name":sub.name,"files":[str(f.relative_to(self.media_dir)) if _is_relative_to(f,self.media_dir) else str(f) for f in counted],"images":[str(f.relative_to(self.media_dir)) if _is_relative_to(f,self.media_dir) else str(f) for f in counted]}
            count+=1
            log_info("marmite::gallery", f"Found gallery: {sub.name} with {len(counted)} files")
        self.galleries=galleries
        log_info("marmite::gallery", f"Total galleries found: {count}")

    def _make_thumbnail(self, src, dest):
        size=int(self.cfg.get('gallery_thumb_size') or 50)
        # PNG support pure python; for other formats copy original as fallback, but if file is fake/corrupt, emulate error log.
        try:
            data=Path(src).read_bytes()
        except Exception as e:
            log_error("marmite::gallery", f"Failed to create thumbnail for {src}: {e}")
            return False
        if data.startswith(b'\x89PNG'):
            try:
                w,h,pixels,mode=_png_decode_rgba(data)
                # resize to width=size (and height proportional; if portrait, height proportional to width may exceed? reference thumbnail for portrait? assume max dimension size preserving aspect by scaling longest side? For 200x100 size50 -> 50x25. For 10x10 -> 50x50. This fits width=size and maxdim both.
                scale=size/max(w,h) if max(w,h)>0 else 1
                # If image is landscape and they resize width exactly, same. Use width scaling if w>=h else height scaling = max dim.
                nw=max(1,round(w*scale)); nh=max(1,round(h*scale))
                resized=_resize_rgba_nearest(w,h,pixels,nw,nh)
                Path(dest).write_bytes(_png_encode_rgba(nw,nh,resized))
                return True
            except Exception as e:
                log_error("marmite::gallery", f"Failed to create thumbnail for {src}: Format error decoding Png: {e}")
                return False
        # Detect JPEG signature; pure copy fallback if valid SOI, can't decode. If fake, error message like reference.
        if src.suffix.lower() in ('.jpg','.jpeg'):
            if not data.startswith(b'\xff\xd8'):
                log_error("marmite::gallery", f"Failed to create thumbnail for {src}: Format error decoding Jpeg: I/O errors Generic I/O error: Cannot satisfy read")
                return False
            # copy as thumbnail (dimension may differ)
            try:
                Path(dest).write_bytes(data); return True
            except Exception:
                return False
        # Other format copy
        try:
            Path(dest).write_bytes(data); return True
        except Exception:
            return False

    # ---- template setup ----
    def _setup_engine(self):
        engine=TeraEngine()
        engine.default_date_format=str(self.cfg.get('default_date_format') or "%b %e, %Y")
        cfg=self.cfg
        url_for=self.url_for_func
        def fn_url_for(args,kwargs,frames,eng):
            if 'path' not in kwargs and not args:
                raise TemplateRenderError("Missing `path` argument")
            path=kwargs.get('path', args[0] if args else None)
            abs_=kwargs.get('abs', args[1] if len(args)>1 else False)
            if path is None or isinstance(path,Undefined):
                # Tera error style inner recognized by caller formatter
                raise TemplateRenderError("Missing `path` argument", var="__url_for_missing_path__")
            return url_for(path, bool(abs_))
        engine.functions['url_for']=fn_url_for
        def fn_group(args,kwargs,frames,eng):
            kind=kwargs.get('kind', args[0] if args else '')
            mp=self._group_maps.get(str(kind),{})
            items=list(mp.items())
            # sort by count desc, stable insertion
            items.sort(key=lambda kv: len(kv[1]), reverse=True)
            return [(k,list(v)) for k,v in items]
        engine.functions['group']=fn_group
        def fn_stream_display(args,kwargs,frames,eng):
            name=kwargs.get('stream', args[0] if args else '')
            return self._display_name('streams', name)
        def fn_series_display(args,kwargs,frames,eng):
            name=kwargs.get('series', args[0] if args else '')
            return self._display_name('series', name)
        engine.functions['stream_display_name']=fn_stream_display
        engine.functions['series_display_name']=fn_series_display
        def fn_source_link(args,kwargs,frames,eng):
            content=kwargs.get('content', args[0] if args else None)
            return self._source_link(content)
        engine.functions['source_link']=fn_source_link
        # embedded templates
        for name,src in TEMPLATES.items():
            try: engine.add_template(name,src)
            except Exception: pass
        # theme templates
        if self.theme_path and self.theme_path.is_dir():
            tdir=self.theme_path/"templates"
            if tdir.is_dir():
                for fp in sorted([p for p in tdir.rglob('*') if p.is_file()]):
                    rel=str(fp.relative_to(tdir))
                    try:
                        engine.add_template(rel, fp.read_text(encoding='utf-8'))
                    except Exception as e:
                        log_error("marmite::site", f"Failed to load template {rel}: Failed to parse '{rel}'")
        # user templates
        if self.templates_dir.is_dir():
            for fp in sorted([p for p in self.templates_dir.rglob('*') if p.is_file()]):
                rel=str(fp.relative_to(self.templates_dir))
                # load .html/.xml and arbitrary extension files that Tera glob would pick; skip hidden?
                try:
                    txt=fp.read_text(encoding='utf-8')
                except Exception:
                    continue
                try:
                    engine.add_template(rel, txt)
                except Exception:
                    log_error("marmite::site", f"Failed to load template {rel}: Failed to parse '{rel}'")
        # custom shortcode templates as templates named shortcodes/<stem>
        sc_dir=self.input_folder/"shortcodes"
        # Debug loading embedded shortcodes (only at debug level; names sorted-ish from embedded list)
        for nm in EMBEDDED_SHORTCODES:
            log_debug("marmite::shortcodes", f"Loaded embedded shortcode: {nm}")
        if sc_dir.is_dir():
            for fp in sorted(sc_dir.glob('*.html')):
                stem=fp.stem
                try:
                    engine.add_template(f"shortcodes/{stem}", fp.read_text(encoding='utf-8'))
                    self.shortcode_defs[stem]=f"shortcodes/{stem}"
                except Exception as e:
                    log_error("marmite::shortcodes", f"Failed to load shortcode {stem}: {e}")
        else:
            log_debug("marmite::shortcodes", f"No shortcodes directory found at {sc_dir}")
        self.engine=engine
        return engine

    def _display_name(self, cfgkey, name):
        if name is None or isinstance(name,Undefined): return ""
        name=str(name)
        mapping=self.cfg.get(cfgkey) or {}
        if isinstance(mapping,dict):
            if name in mapping and isinstance(mapping[name],dict) and mapping[name].get('display_name'):
                return mapping[name]['display_name']
            sl=slugify(name)
            if sl in mapping and isinstance(mapping[sl],dict) and mapping[sl].get('display_name'):
                return mapping[sl]['display_name']
        return name

