    # ---- shortcodes ----
    def _process_shortcodes(self, html_text, context):
        pattern_str=self.cfg.get('shortcode_pattern') or r'<!-- \.(\w+)(?:\s+([^-][\s\S]*?))?\s*-->'
        try:
            pattern=re.compile(pattern_str)
        except Exception:
            pattern=re.compile(r'<!-- \.(\w+)(?:\s+([^-][\s\S]*?))?\s*-->')
        def repl(m):
            full=m.group(0)
            name=m.group(1) if m.lastindex and m.lastindex>=1 else ''
            params=m.group(2) if m.lastindex and m.lastindex>=2 and m.group(2) else ''
            log_info("marmite::shortcodes", f"Processing shortcode: name='{name}', params='{params}', full_match='{full}'")
            try:
                return self._render_shortcode(name, params, context)
            except ShortcodeRenderError as e:
                msg=e.msg
                log_warn("marmite::shortcodes", f"Shortcode '{name}' failed to render: {msg}")
                esc=msg.replace("'","&#39;")
                return f'<div class="shortcode-error" style="border: 2px solid red; padding: 10px; margin: 10px 0; background-color: #ffeeee; color: #cc0000;">\n                        <strong>Shortcode Error:</strong> {esc}</div>'
            except Exception as e:
                msg=f"Failed to render shortcode '{name}': Failed to render '__tera_one_off'"
                log_warn("marmite::shortcodes", f"Shortcode '{name}' failed to render: {msg}")
                esc=msg.replace("'","&#39;")
                return f'<div class="shortcode-error" style="border: 2px solid red; padding: 10px; margin: 10px 0; background-color: #ffeeee; color: #cc0000;">\n                        <strong>Shortcode Error:</strong> {esc}</div>'
        return pattern.sub(repl, html_text)

    def _render_shortcode(self, name, params, context):
        # custom shortcode overrides embedded
        if name in self.shortcode_defs:
