def _parse_shortcode_params(params, keep_raw=False):
    kwargs={}; positional=[]
    if not params: return kwargs,positional
    tokens=[]; cur=''; in_s=False; in_d=False
    for ch in params:
        if in_s:
            cur+=ch
            if ch=="'": in_s=False
        elif in_d:
            cur+=ch
            if ch=='"': in_d=False
        else:
            if ch=="'": in_s=True; cur+=ch
            elif ch=='"': in_d=True; cur+=ch
            elif ch.isspace():
                if cur: tokens.append(cur); cur=''
            else: cur+=ch
    if cur: tokens.append(cur)
    for tok in tokens:
        if '=' in tok and re.match(r'^[A-Za-z_][A-Za-z0-9_]*=', tok):
            k,v=tok.split('=',1)
            if len(v)>=2 and ((v[0]=='"' and v[-1]=='"') or (v[0]=="'" and v[-1]=="'")):
                v=v[1:-1]
            kwargs[k]=v
        else:
            positional.append(tok)
    return kwargs,positional

