# PNG utilities for thumbnails
def _png_decode_rgba(data):
    if not data.startswith(b'\x89PNG\r\n\x1a\n'):
        raise ValueError("not png")
    pos=8; idat=b''; w=h=None; bitdepth=None; colortype=None; palette=None; trns=None
    while pos < len(data):
        if pos+8>len(data): break
        length=struct.unpack('>I',data[pos:pos+4])[0]; typ=data[pos+4:pos+8]; chunk=data[pos+8:pos+8+length]; pos+=8+length+4
        if typ==b'IHDR':
            w,h,bitdepth,colortype=struct.unpack('>IIBB',chunk[:10])
        elif typ==b'PLTE': palette=chunk
        elif typ==b'tRNS': trns=chunk
        elif typ==b'IDAT': idat+=chunk
        elif typ==b'IEND': break
    if w is None: raise ValueError("no IHDR")
    raw=zlib.decompress(idat)
    # bytes per pixel by colortype/bitdepth (support 8-bit types 0,2,3,4,6; and 16-bit crude high byte)
    channels={0:1,2:3,3:1,4:2,6:4}.get(colortype)
    if channels is None: raise ValueError("unsupported colortype")
    if bitdepth not in (8,16,1,2,4):
        raise ValueError("unsupported bitdepth")
    # Only handle 8 and 16 fully; subbyte grayscale/palette handle basic unpacking below for bitdepth<8 color0/3
    if bitdepth==8:
        bpp=channels; stride=w*channels
    elif bitdepth==16:
        bpp=channels*2; stride=w*channels*2
    else:
        # packed
        bpp=1; stride=(w*bitdepth+7)//8
    pixels=[]  # list of rows of RGBA tuples flattened
    prev=bytearray(stride)
    p=0
    rgba=bytearray()
    for y in range(h):
        filt=raw[p]; p+=1; line=bytearray(raw[p:p+stride]); p+=stride
        # unfilter
        for x in range(stride):
            left=line[x-bpp] if x>=bpp else 0
            up=prev[x] if y>0 else 0
            upleft=prev[x-bpp] if y>0 and x>=bpp else 0
            if filt==1: line[x]=(line[x]+left)&0xff
            elif filt==2: line[x]=(line[x]+up)&0xff
            elif filt==3: line[x]=(line[x]+((left+up)//2))&0xff
            elif filt==4:
                pa=abs(up-upleft); pb=abs(left-upleft); pc=abs(left+up-upleft-upleft)
                # Paeth
                a=left; b=up; c=upleft; pp=a+b-c; pa=abs(pp-a); pb=abs(pp-b); pc=abs(pp-c)
                pr=a if (pa<=pb and pa<=pc) else (b if pb<=pc else c)
                line[x]=(line[x]+pr)&0xff
        prev=line
        # convert to rgba
        if bitdepth==8:
            for x in range(w):
                off=x*channels
                if colortype==6: rgba.extend(line[off:off+4])
                elif colortype==2: rgba.extend((line[off],line[off+1],line[off+2],255))
                elif colortype==0: g=line[off]; rgba.extend((g,g,g,255))
                elif colortype==4: g=line[off]; rgba.extend((g,g,g,line[off+1]))
                elif colortype==3:
                    idx=line[off]; r=palette[idx*3] if palette and idx*3 < len(palette) else idx; g=palette[idx*3+1] if palette and idx*3+1 < len(palette) else idx; b=palette[idx*3+2] if palette and idx*3+2 < len(palette) else idx; a=trns[idx] if trns and idx < len(trns) else 255; rgba.extend((r,g,b,a))
        elif bitdepth==16:
            for x in range(w):
                vals=[line[(x*channels+i)*2] for i in range(channels)]
                if colortype==6: rgba.extend(vals)
                elif colortype==2: rgba.extend((vals[0],vals[1],vals[2],255))
                elif colortype==0: rgba.extend((vals[0],vals[0],vals[0],255))
                elif colortype==4: rgba.extend((vals[0],vals[0],vals[0],vals[1]))
                else: rgba.extend((vals[0],vals[0],vals[0],255))
        else:
            # packed grayscale/palette
            maxv=(1<<bitdepth)-1
            for x in range(w):
                byte_index=(x*bitdepth)//8; shift=8-((x*bitdepth)%8)-bitdepth; val=(line[byte_index]>>shift)&maxv
                if colortype==3 and palette:
                    idx=val; r=palette[idx*3]; g=palette[idx*3+1]; b=palette[idx*3+2]; rgba.extend((r,g,b,255))
                else:
                    g=int(val*255/maxv) if maxv else 0; rgba.extend((g,g,g,255))
    return w,h,bytes(rgba), 'RGBA'

def _resize_rgba_nearest(w,h,pixels,nw,nh):
    out=bytearray()
    for y in range(nh):
        sy=min(h-1,int(y*h/nh))
        for x in range(nw):
            sx=min(w-1,int(x*w/nw)); off=(sy*w+sx)*4; out.extend(pixels[off:off+4])
    return bytes(out)

def _png_encode_rgba(w,h,pixels):
    def chunk(typ,data):
        return struct.pack('>I',len(data))+typ+data+struct.pack('>I',zlib.crc32(typ+data)&0xffffffff)
    raw=b''.join(b'\x00'+pixels[y*w*4:(y+1)*w*4] for y in range(h))
    return b'\x89PNG\r\n\x1a\n'+chunk(b'IHDR',struct.pack('>IIBBBBB',w,h,8,6,0,0,0))+chunk(b'IDAT',zlib.compress(raw))+chunk(b'IEND',b'')

