                col=len(stripped); line=1
            else:
                lines=stripped.split('\n'); line=len(lines); col=len(lines[-1])+1
            log_error("marmite::theme_manager", f"Failed to read theme metadata: missing field `{field}` at line {line} column {col}")
            return 0
    return _apply_theme_metadata(args, source, meta)

def _apply_theme_metadata(args, source, meta):
    cfg_path=cfg_path_for(args['input_folder'], args.get('config') or 'marmite.yaml')
    if cfg_path.is_file():
        log_info("marmite::theme_manager", f"Updating marmite.yaml with theme: {source}")
        try:
            text=cfg_path.read_text(encoding='utf-8')
            parsed=parse_yaml(text) if text.strip() else {}
            if not isinstance(parsed,dict): parsed={}
            parsed['theme']=source
            cfg_path.write_text(dump_yaml(parsed),encoding='utf-8')
        except Exception as e:
            # Fallback append
            try:
                with open(cfg_path,'a',encoding='utf-8') as f:
                    f.write(f"theme: {source}\n")
            except Exception:
                pass
    else:
        log_info("marmite::theme_manager", f"Creating new marmite.yaml with theme: {source}")
        cfg=generated_config_defaults()
        # CLI overrides (theme arg itself is set below)
        for k,v in cli_overrides(args).items():
            if k in cfg: cfg[k]=v
        cfg['theme']=source
        cfg_path.parent.mkdir(parents=True,exist_ok=True)
        cfg_path.write_text(dump_config_yaml(cfg),encoding='utf-8')
    # stdout success message
    features=meta.get('features') or []
    tags=meta.get('tags') or []
    out=[]
    out.append(f"\n✅ Theme '{source}' has been successfully set!\n")
    out.append("\n📦 Theme Information:")
    out.append(f"   Name: {meta.get('name','')}")
    out.append(f"   Version: {meta.get('version','')}")
    out.append(f"   Author: {meta.get('author','')}")
    out.append(f"   Description: {meta.get('description','')}")
    if features:
        out.append("\n✨ Features:")
        for f in features:
            out.append(f"   - {f}")
    if tags:
        out.append(f"\n🏷️  Tags: {', '.join(str(t) for t in tags)}")
    out.append(f"\n🚀 To use this theme, run: marmite {args['input_folder']} --theme {source}")
    sys.stdout.write("\n".join(out)+"\n")
    return 0

def op_generate_config(args):
    cfg_path=cfg_path_for(args['input_folder'], args.get('config') or 'marmite.yaml')
    if cfg_path.exists():
        log_error("marmite::config", f"Config file already exists: {cfg_path}")
