# server / watch
def serve_http(output_dir, bind):
    log_info("marmite::server", f"Server started at http://{bind}/ - Type ^C to stop.")
    # parse bind
    if ':' in bind:
        host,port_s=bind.rsplit(':',1)
        try: port=int(port_s)
        except Exception:
            log_error("marmite::server", f"Failed to bind to {bind}")
            return 1
    else:
        host='0.0.0.0'; port=8000
    import socketserver
    class Handler(socketserver.BaseRequestHandler):
        def handle(self):
            try:
                data=b''
                while b'\r\n\r\n' not in data and len(data)<65536:
                    chunk=self.request.recv(4096)
                    if not chunk: break
                    data+=chunk
                if not data: return
                line=data.split(b'\r\n',1)[0].decode('utf-8','ignore')
                parts=line.split()
                method=parts[0] if parts else 'GET'
                raw_path=parts[1] if len(parts)>1 else '/'
                version=parts[2] if len(parts)>2 else 'HTTP/1.1'
                parsed=urllib.parse.urlsplit(raw_path)
                path=urllib.parse.unquote(parsed.path)
                if path=='/' or path=='':
                    rel='index.html'
                else:
                    rel=path.lstrip('/')
                file_path=Path(output_dir)/rel
                status=200; log_status=200
                if file_path.is_dir():
                    # try index inside?
                    cand=file_path/'index.html'
                    if cand.is_file():
                        file_path=cand; rel=str(Path(rel)/'index.html')
                    else:
                        file_path=Path(output_dir)/'404.html'; log_status=404
                elif not file_path.is_file():
                    file_path=Path(output_dir)/'404.html'; log_status=404
                body=b''
                if file_path.is_file():
                    body=file_path.read_bytes()
                else:
                    body=b'404 Not Found'
                # log before/after response (reference logs after request)
                if log_status==200:
                    log_info("marmite::server", f'"{method} {rel} {version}" 200 -')
                else:
                    log_error("marmite::server", f'"{method} {rel} {version}" 404 -')
                date_hdr=datetime.now(timezone.utc).strftime('%a, %d %b %Y %H:%M:%S GMT')
                resp=f"HTTP/1.1 200 OK\r\nServer: tiny-http (Rust)\r\nDate: {date_hdr}\r\nContent-Length: {len(body)}\r\n\r\n".encode()
                self.request.sendall(resp+body)
            except Exception:
                return
    class Server(socketserver.ThreadingTCPServer):
        allow_reuse_address=True; daemon_threads=True
    try:
        srv=Server((host,port),Handler)
    except OSError as e:
        log_error("marmite::server", f"Failed to bind to {bind}: {rust_os_error(e)}")
        return 1
    try:
        srv.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        try: srv.server_close()
        except Exception: pass
    return 0

def start_server_thread(output_dir, bind):
    t=threading.Thread(target=serve_http,args=(output_dir,bind),daemon=True)
    t.start(); return t

def snapshot_files(folder, exclude_paths):
    snap={}
    folder=Path(folder)
    excludes=[Path(p).resolve() if str(p) else None for p in exclude_paths]
    for root,dirs,files in os.walk(folder):
        # exclude output dirs
        rp=Path(root)
        # prune excluded dirs
        dirs[:] = [d for d in dirs if not any(ex and (rp/d).resolve()==ex or _is_relative_to((rp/d).resolve(), ex) for ex in excludes if ex)]
        for f in files:
            fp=rp/f
            try:
                st=fp.stat(); snap[str(fp)]=(st.st_mtime,st.st_size)
            except Exception:
                pass
    return snap

def build_site_once(args):
    site=make_site(args, load_data=False)
    site.generate()
    return site

def main(argv=None):
    global LOG_LEVEL, PROG
    if argv is None: argv=sys.argv[1:]
    PROG=os.path.basename(sys.argv[0]) or 'executable'
    try:
        args=parse_cli(argv)
    except ClapExit as e:
        return e.code
    # logging level
    v=int(args.get('verbose') or 0)
    if v<=0: LOG_LEVEL=30
    elif v==1: LOG_LEVEL=20
    elif v==2: LOG_LEVEL=10
    else: LOG_LEVEL=5
    force_info_ops=['init_templates','start_theme','set_theme','generate_config','init_site','watch','serve']
    if any(args.get(k) for k in force_info_ops) or args.get('start_theme') is not None or args.get('set_theme') is not None:
        if LOG_LEVEL>20: LOG_LEVEL=20
    input_folder=args['input_folder']
    if not Path(input_folder).exists():
        log_error("marmite", f'Input folder does not exist: "{input_folder}"')
        return 1
    try:
        # precedence
        if args.get('init_site'):
            return op_init_site(args)
        if args.get('new') is not None:
            return op_new(args)
        if args.get('init_templates'):
            return op_init_templates(args)
        if args.get('start_theme') is not None:
            return op_start_theme(args)
        if args.get('set_theme') is not None:
            return op_set_theme(args)
        if args.get('generate_config'):
            return op_generate_config(args)
        if args.get('shortcodes'):
            return op_shortcodes(args)
        if args.get('show_urls'):
            return op_show_urls(args)
        # normal generation
        if args.get('watch'):
            # initial build
            site=build_site_once(args)
            log_info("marmite::site", f"Watching for changes in folder: {input_folder}")
            server_thread=None
            if args.get('serve'):
                log_info("marmite::site", "Starting built-in HTTP server...")
                server_thread=start_server_thread(site.output_folder, args.get('bind') or '0.0.0.0:8000')
            exclude=[site.output_folder, site.site_output]
            snap=snapshot_files(input_folder, exclude)
            try:
                while True:
                    time.sleep(0.5)
                    new_snap=snapshot_files(input_folder, exclude)
                    if new_snap!=snap:
                        snap=new_snap
                        log_info("marmite::site", "Change detected. Rebuilding site...")
                        try:
                            site=build_site_once(args)
                            snap=snapshot_files(input_folder, exclude)
                        except SiteFatal:
                            # watch continues after rebuild failure in reference? Keep watching
                            snap=snapshot_files(input_folder, exclude)
            except KeyboardInterrupt:
                return 0
        else:
            site=build_site_once(args)
            if args.get('serve'):
                log_info("marmite", "Starting built-in HTTP server...")
                return serve_http(site.output_folder, args.get('bind') or '0.0.0.0:8000')
            return 0
    except SiteFatal as e:
        return e.code
    except KeyboardInterrupt:
        return 0

if __name__=='__main__':
    sys.exit(main())

