        (input_path/'custom.css').write_text(INIT_CUSTOM_CSS,encoding='utf-8')
        (input_path/'custom.js').write_text(INIT_CUSTOM_JS,encoding='utf-8')
        # config
        cfg_path.parent.mkdir(parents=True,exist_ok=True)
        cfg_path.write_text(dump_config_yaml(cfg),encoding='utf-8')
        log_info("marmite::config", f"Config file generated: {cfg_path}")
    except OSError as e:
        log_error("marmite::site", f"Failed to initialize site: {rust_os_error(e)}")
        return 1
    log_info("marmite::site", f"Site initialized in {args['input_folder']}")
    return 0

def op_new(args):
    # load config for content_path
    try:
        site_cfg,cfg_path,loaded=load_config(args['input_folder'], args.get('config') or 'marmite.yaml', cli_overrides(args))
    except ConfigError as e:
        log_error("marmite::site", f"Failed to parse config YAML: {e.msg}")
        return 1
    # replicate config loaded logs that load_config/site would make? In reference, --new loads site config via Marmite::new? It logged Unable/Config loaded at info.
    # load_config already logs Unable... if missing. Also log config loaded:
    log_info("marmite::site", f"Config loaded from: {loaded}")
    input_path=Path(args['input_folder'])
    content_name=str(site_cfg.get('content_path') or 'content')
    cand=Path(content_name) if os.path.isabs(content_name) else input_path/content_name
    target_dir=cand if cand.is_dir() else (input_path if input_path.is_dir() else input_path.parent)
    title=args.get('new') or ''
    slug=slugify(title)
    if args.get('page'):
        filename=f"{slug}.md"
    else:
        ts=datetime.now().strftime('%Y-%m-%d-%H-%M-%S')
        filename=f"{ts}-{slug}.md"
    out_path=target_dir/filename
    if args.get('tags') is not None:
        content=f"---\ntags: {args['tags']}\n---\n# {title}\n\n"
    else:
        content=f"# {title}\n"
    try:
        out_path.write_text(content,encoding='utf-8')
    except OSError as e:
        log_error("marmite::content", f"Failed to create file: {rust_os_error(e)}")
