    if args.get('edit'):
        editor=os.environ.get('EDITOR') or os.environ.get('VISUAL') or 'vi'
        # edit crate-like: if editor string empty or contains spaces as whole program name, spawn fails NotFound
        import subprocess
        try:
            subprocess.run([editor, str(out_path)], check=False)
        except FileNotFoundError:
            log_error("marmite::content", 'Failed to open editor: Os { code: 2, kind: NotFound, message: "No such file or directory" }')
        except OSError as e:
            log_error("marmite::content", f"Failed to open editor: {rust_os_error(e)}")
