# ---------------- Operations ----------------
def cfg_path_for(input_folder, config_arg):
    return Path(config_arg) if os.path.isabs(str(config_arg)) else Path(input_folder)/str(config_arg)

def make_site(args, load_data=False, process_galleries=False):
    input_folder=args['input_folder']
    overrides=cli_overrides(args)
    try:
        cfg,cfg_path,loaded=load_config(input_folder, args.get('config') or 'marmite.yaml', overrides, for_generate=False)
    except ConfigError as e:
        log_error("marmite::site", f"Failed to parse config YAML: {e.msg}")
        raise SiteFatal(1)
    site=Site(input_folder, args.get('output_folder'), cfg, cfg_path, loaded, force_render=bool(args.get('force')))
    if load_data:
        site.load_data(process_galleries=process_galleries)
    return site

def op_init_site(args):
    input_path=Path(args['input_folder'])
    try:
        entries=list(input_path.iterdir()) if input_path.is_dir() else [input_path]
    except Exception:
        entries=[]
    if entries:
        log_error("marmite::site", f"Input folder is not empty: {args['input_folder']}")
        return 1
    # generated config with overrides
    overrides=cli_overrides(args)
    cfg=generated_config_defaults()
    for k,v in overrides.items():
        if k=='colorscheme':
            extra={}; extra['colorscheme']=v; cfg['extra']=extra
        elif k in cfg: cfg[k]=v
    cfg_path=cfg_path_for(args['input_folder'], args.get('config') or 'marmite.yaml')
    # content dir
    content_name=str(cfg.get('content_path') or 'content')
    content_dir=Path(content_name) if os.path.isabs(content_name) else input_path/content_name
    try:
        content_dir.mkdir(parents=True, exist_ok=True)
        (content_dir/'media').mkdir(parents=True, exist_ok=True)
        today=datetime.now().strftime('%Y-%m-%d')
        for rel,content in INIT_CONTENT.items():
            dest_name=f"{today}-welcome.md" if rel=='welcome.md' else rel
            dest=content_dir/dest_name
            dest.parent.mkdir(parents=True,exist_ok=True)
