        (input_path/'custom.css').write_text(INIT_CUSTOM_CSS,encoding='utf-8')
        (input_path/'custom.js').write_text(INIT_CUSTOM_JS,encoding='utf-8')
        # config
        cfg_path.parent.mkdir(parents=True,exist_ok=True)
        cfg_path.write_text(dump_config_yaml(cfg),encoding='utf-8')
        log_info("marmite::config", f"Config file generated: {cfg_path}")
    except OSError as e:
        log_error("marmite::site", f"Failed to initialize site: {rust_os_error(e)}")
        return 1
    log_info("marmite::site", f"Site initialized in {args['input_folder']}")
