    # load_config already logs Unable... if missing. Also log config loaded:
    log_info("marmite::site", f"Config loaded from: {loaded}")
    input_path=Path(args['input_folder'])
    content_name=str(site_cfg.get('content_path') or 'content')
    cand=Path(content_name) if os.path.isabs(content_name) else input_path/content_name
    target_dir=cand if cand.is_dir() else (input_path if input_path.is_dir() else input_path.parent)
    title=args.get('new') or ''
    slug=slugify(title)
    if args.get('page'):
