        # README
        dest=theme_dir/'README.md'; dest.write_text(THEME_README,encoding='utf-8'); log_info("marmite::templates", f"Generated {dest}")
        # static
        for fname,data in sorted(_zip_names_data(THEME_STATIC_ZIP_B64), key=lambda x:x[0]):
            dest=theme_dir/'static'/fname; dest.parent.mkdir(parents=True,exist_ok=True); dest.write_bytes(data); log_info("marmite::templates", f"Generated {dest}")
        for tname in THEME_TEMPLATES_ORDER:
            dest=theme_dir/'templates'/tname; dest.parent.mkdir(parents=True,exist_ok=True); dest.write_text(THEME_TEMPLATES[tname],encoding='utf-8'); log_info("marmite::templates", f"Generated {dest}")
        dest=theme_dir/'theme.json'; dest.write_text(THEME_JSON,encoding='utf-8'); log_info("marmite::templates", f"Generated {dest}")
    except OSError as e:
