    return 0

def op_set_theme(args):
    source=args.get('set_theme') or ''
    log_info("marmite::theme_manager", f"Setting theme from: {source}")
    if source.startswith('http://') or source.startswith('https://'):
        log_info("marmite::theme_manager", f"Downloading theme from: {source}")
        # Attempt download; remote themes are expected to be .zip archives
        try:
            req=urllib.request.Request(source, headers={'User-Agent':'marmite'})
            with urllib.request.urlopen(req, timeout=10) as resp:
                data=resp.read()
        except Exception as e:
            # map DNS error to reference message
            reason=getattr(e,'reason',e)
            if isinstance(reason, socket.gaierror) or 'Name or service not known' in str(e) or 'Temporary failure in name resolution' in str(e):
                log_error("marmite::theme_manager", "Failed to download theme: io: failed to lookup address information: Temporary failure in name resolution")
            else:
                log_error("marmite::theme_manager", f"Failed to download theme: {e}")
            return 0
        # Try treat as zip containing theme.json at root or subfolder
        try:
            z=zipfile.ZipFile(io.BytesIO(data))
            names=z.namelist()
            tj_name=None
            for n in names:
                if n.endswith('theme.json'):
                    tj_name=n; break
            if tj_name is None:
                log_error("marmite::theme_manager", f"theme.json not found in theme folder: {source}")
                return 0
            meta=json.loads(z.read(tj_name).decode('utf-8'))
        except Exception as e:
            log_error("marmite::theme_manager", f"Failed to download theme: {e}")
            return 0
        return _apply_theme_metadata(args, source, meta)
    theme_folder=Path(source) if os.path.isabs(source) else Path(args['input_folder'])/source
    if not theme_folder.exists():
        log_error("marmite::theme_manager", f"Theme folder does not exist: {source}")
        return 0
    theme_json=theme_folder/'theme.json'
    if not theme_json.is_file():
        log_error("marmite::theme_manager", f"theme.json not found in theme folder: {source}")
        return 0
    try:
        raw=theme_json.read_text(encoding='utf-8')
        meta=json.loads(raw)
    except Exception as e:
        # serde json error message approx: include line/col if available
        msg=str(e)
        log_error("marmite::theme_manager", f"Failed to read theme metadata: {msg}")
        return 0
    if not isinstance(meta,dict):
        log_error("marmite::theme_manager", "Failed to read theme metadata: invalid type")
        return 0
    required=["name","version","author","description"]
    for field in required:
        if field not in meta:
            # column approx end of first line / object end (serde reports at closing brace)
            # compute line/col of closing brace in raw (last })
            # simplified: line 1 col len(raw.strip()) for single-line, else count
            stripped=raw.rstrip()
            if '\n' not in stripped:
                col=len(stripped); line=1
            else:
                lines=stripped.split('\n'); line=len(lines); col=len(lines[-1])+1
            log_error("marmite::theme_manager", f"Failed to read theme metadata: missing field `{field}` at line {line} column {col}")
            return 0
    return _apply_theme_metadata(args, source, meta)

def _apply_theme_metadata(args, source, meta):
    cfg_path=cfg_path_for(args['input_folder'], args.get('config') or 'marmite.yaml')
    if cfg_path.is_file():
        log_info("marmite::theme_manager", f"Updating marmite.yaml with theme: {source}")
        try:
            text=cfg_path.read_text(encoding='utf-8')
            parsed=parse_yaml(text) if text.strip() else {}
            if not isinstance(parsed,dict): parsed={}
            parsed['theme']=source
            cfg_path.write_text(dump_yaml(parsed),encoding='utf-8')
        except Exception as e:
            # Fallback append
            try:
                with open(cfg_path,'a',encoding='utf-8') as f:
                    f.write(f"theme: {source}\n")
            except Exception:
                pass
    else:
        log_info("marmite::theme_manager", f"Creating new marmite.yaml with theme: {source}")
        cfg=generated_config_defaults()
        # CLI overrides (theme arg itself is set below)
        for k,v in cli_overrides(args).items():
            if k in cfg: cfg[k]=v
        cfg['theme']=source
        cfg_path.parent.mkdir(parents=True,exist_ok=True)
        cfg_path.write_text(dump_config_yaml(cfg),encoding='utf-8')
    # stdout success message
    features=meta.get('features') or []
    tags=meta.get('tags') or []
    out=[]
    out.append(f"\n✅ Theme '{source}' has been successfully set!\n")
    out.append("\n📦 Theme Information:")
    out.append(f"   Name: {meta.get('name','')}")
    out.append(f"   Version: {meta.get('version','')}")
    out.append(f"   Author: {meta.get('author','')}")
    out.append(f"   Description: {meta.get('description','')}")
    if features:
        out.append("\n✨ Features:")
        for f in features:
            out.append(f"   - {f}")
    if tags:
        out.append(f"\n🏷️  Tags: {', '.join(str(t) for t in tags)}")
    out.append(f"\n🚀 To use this theme, run: marmite {args['input_folder']} --theme {source}")
    sys.stdout.write("\n".join(out)+"\n")
    return 0

